const t=e=>e.mode==="gallery",a=[{id:"l.rc-element-details.rows",xp:30,title:{en:"Crowd the bars until a third row is needed — never a fourth",ar:"زحم الأسياخ لحد ما يلزم صف تالت — ورابع لأ"},check:e=>t(e)&&e.g.item==="beam"&&e.g.beamRows===3},{id:"l.rc-element-details.shrink",xp:30,title:{en:"Make the web more than 600 mm deep below the slab: side bars appear",ar:"خلّي جسم الكمرة أعمق من 600 مم تحت البلاطة: حديد الجوانب بيظهر"},check:e=>t(e)&&e.g.item==="beam"&&e.g.beamShrink>0},{id:"l.rc-element-details.mix",xp:30,title:{en:"Mix two diameters that are not neighbours and let the checker refuse it",ar:"اخلط قطرين مش متجاورين وخلّي المراجعة ترفضهم"},hint:{en:'Pick Ø18 or larger, then "two sizes smaller".',ar:"اختار Ø18 أو أكبر، وبعدين «أصغر بمقاسين»."},check:e=>t(e)&&e.g.item==="beam"&&e.g.beamMix==="skip"&&!e.g.beamMixOk}],n=[{id:"l.rc-element-details.fatal",xp:30,title:{en:"Open the knee and bend the tension bar round its inner corner: watch the cover go",ar:"خلّي الركن يفتح واثني سيخ الشد حوالين الركن الداخلي: شوف الغطاء بيروح"},check:e=>t(e)&&e.g.item==="knee"&&e.g.kneeVerdict==="fatal"},{id:"l.rc-element-details.scissors",xp:30,title:{en:"Fix the opening knee of a beam with scissors",ar:"صلّح الركن اللي بيفتح في كمرة بالمقص"},check:e=>t(e)&&e.g.item==="knee"&&e.g.kneeAction==="opening"&&e.g.kneeDetail==="scissors"&&e.g.kneeMember==="beam"},{id:"l.rc-element-details.bow",xp:30,title:{en:"Fix the opening corner of a slab with a bow (loop)",ar:"صلّح الركن اللي بيفتح في بلاطة بالفيونكة"},check:e=>t(e)&&e.g.item==="knee"&&e.g.kneeAction==="opening"&&e.g.kneeDetail==="bow"&&e.g.kneeMember==="slab"},{id:"l.rc-element-details.joint3",xp:40,title:{en:"Build the three-member joint step by step, up to the scissors",ar:"ابني عقدة التلات عناصر خطوة خطوة لحد المقص"},check:e=>t(e)&&e.g.item==="joint3"&&e.g.jointStep==="scissors"}],o=[{id:"l.rc-element-details.inner",xp:40,title:{en:"Build a column that needs inner ties and make every tie rule green",ar:"ابني عمود محتاج كانات داخلية وخلّي كل قواعد الكانات خضرا"},check:e=>t(e)&&e.g.item==="column"&&e.g.colNeedsInner&&e.g.colTiesOk},{id:"l.rc-element-details.eye",xp:30,title:{en:'Try a single wound "eye" bar where inner ties are needed',ar:"جرّب كانة العيون الملفوفة في مكان محتاج كانات داخلية"},check:e=>t(e)&&e.g.item==="column"&&e.g.colLayout==="eye"&&e.g.colNeedsInner},{id:"l.rc-element-details.fire",xp:30,title:{en:"Find an exposure case or a fire rating that the usual cage cannot meet",ar:"لاقي حالة تعرض أو مقاومة حريق القفص العادي مايقدرش يحققها"},check:e=>t(e)&&e.g.item==="column"&&!e.g.colCoverOk},{id:"l.rc-element-details.crank",xp:40,title:{en:"Make the crank steeper than 1 : 6, then switch to separate splice bars",ar:"خلّي التكسيح أحد من 1 : 6، وبعدين حوّل لأشاير منفصلة"},check:e=>t(e)&&e.g.item==="dowels"&&!e.g.crankOk&&e.g.dowelDetail==="splice"}],s=[{id:"l.rc-element-details.parapet",xp:20,title:{en:"Put a parapet on the cantilever and follow its U-bars",ar:"حط دروة على الكابولي وتابع أسياخ U بتاعتها"},check:e=>t(e)&&e.g.item==="cantilever"&&e.g.cantParapet},{id:"l.rc-element-details.corner",xp:40,title:{en:"A corner cantilever longer than 1.0 m: find a solution that works",ar:"ركن كابولي أطول من 1.0 م: لاقي حل ينفع"},check:e=>t(e)&&e.g.item==="corner"&&e.g.cornerLc>1&&e.g.cornerOk===!0},{id:"l.rc-element-details.simple",xp:30,title:{en:"Design every bay of a continuous strip as simple and see where it cracks",ar:"صمّم كل باكية في شريحة مستمرة كأنها بسيطة وشوف بتتشرخ فين"},check:e=>t(e)&&e.g.item==="slabstrip"&&e.g.stripSimple&&e.g.stripSpans>1},{id:"l.rc-element-details.thick",xp:20,title:{en:"Thicken the strip beyond 160 mm: a top mesh takes over",ar:"تخّن الشريحة فوق 160 مم: شبكة علوية بتستلم"},check:e=>t(e)&&e.g.item==="slabstrip"&&e.g.stripTs>160}],r=[{id:"l.rc-element-details.dowel",xp:30,title:{en:"Deepen the footing until the dowels fit straight, 40Ø",ar:"عمّق القاعدة لحد ما الأشاير تدخل مستقيمة 40Ø"},check:e=>t(e)&&e.g.item==="footing"&&e.g.ftStraight},{id:"l.rc-element-details.combined",xp:20,title:{en:"Switch to a combined footing and find its hidden beams",ar:"حوّل لقاعدة مشتركة ودوّر على كمراتها المدفونة"},check:e=>t(e)&&e.g.item==="strap"&&e.g.strapKind==="combined"},{id:"l.rc-element-details.drop",xp:20,title:{en:"Remove the drop panel and read the new column-strip extent",ar:"شيل السقوط واقرا امتداد شريحة العمود الجديد"},check:e=>t(e)&&e.g.item==="flat"&&!e.g.flatDrop},{id:"l.rc-element-details.crossrib",xp:30,title:{en:"Hollow blocks: give a one-way slab the cross rib it needs",ar:"هوردي: ادّي البلاطة اللي في اتجاه واحد العصب العرضي اللي محتاجاه"},check:e=>t(e)&&e.g.item==="hollow"&&e.g.hbSystem==="one-way"&&e.g.hbCross>0&&e.g.hbCrossOn}],i={sections:[{id:"recap",title:{en:"What the bars already know: bond, laps and cut-offs",ar:"اللي الأسياخ عارفاه: التماسك والوصلات وتوقيف الحديد"},blocks:[{t:"p",text:{en:"Design gives areas of steel; the drawings give every bar a place, a shape and a length. The two detailing episodes before this one (the empirical method and the moment of resistance) built the tools on **beams**: how long a bar must be to work, where it may stop, how it is anchored and joined. This episode takes those tools to **every other element** — beam sections and joints, columns, tension members, frames, solid, flat and hollow-block slabs and the foundations — through a 3-D gallery of details. First, the tools in one table.",ar:"التصميم بيديك مساحات حديد؛ واللوحات بتدّي كل سيخ مكانه وشكله وطوله. الحلقتين اللي قبل دي (الطريقة التقريبية وطريقة عزم المقاومة) بنوا الأدوات على **الكمرات**: السيخ محتاج قد إيه علشان يشتغل، وممكن يقف فين، وبيتثبت ويتوصل إزاي. الحلقة دي بتاخد الأدوات دي لـ**كل العناصر التانية** — قطاعات الكمرات وعقدها، والأعمدة، وعناصر الشد، والإطارات، والبلاطات المصمتة واللاكمرية والهوردي، والأساسات — من خلال معرض 3D للتفاصيل. الأول، الأدوات في جدول واحد."}},{t:"table",head:[{en:"Rule",ar:"القاعدة"},{en:"What to use",ar:"بنستخدم إيه"}],rows:[[{en:"Development length",ar:"طول التماسك"},{en:"$L_d = \\alpha\\beta\\eta\\,\\phi\\,(f_y/\\gamma_s)/(4f_{bu})$ with $f_{bu} = 0.30\\sqrt{f_{cu}/\\gamma_c}$, never below 300 mm; in practice 60Ø·η in tension and 40Ø in compression (η = 1.3 for top bars)",ar:"$L_d = \\alpha\\beta\\eta\\,\\phi\\,(f_y/\\gamma_s)/(4f_{bu})$ و $f_{bu} = 0.30\\sqrt{f_{cu}/\\gamma_c}$، ومش أقل من 300 مم؛ وعملياً 60Ø·η في الشد و 40Ø في الضغط (η = 1.3 للأسياخ العلوية)"}],[{en:"Anchorage",ar:"التثبيت"},{en:"bottom bars $\\max(d,\\ 10\\phi + 0.3d)$; top bars also at least $L/20 + 0.3d$ (L = the bigger span)",ar:"الحديد السفلي $\\max(d,\\ 10\\phi + 0.3d)$؛ والعلوي كمان مش أقل من $L/20 + 0.3d$ (L = البحر الأكبر)"}],[{en:"Tension laps",ar:"وصلات الشد بالتراكب"},{en:"class A 1.0 L_d (As,prov/As,req ≥ 2 and ≤ 50 % spliced at a section), otherwise class B 1.3 L_d; a member in pure tension is joined only by couplers or welding",ar:"فئة A = 1.0 L_d (As,prov/As,req ≥ 2 و ≤ 50% متوصلين في قطاع)، غير كده فئة B = 1.3 L_d؛ والعنصر المشدود بالكامل بيتوصل بالجلب أو اللحام بس"}],[{en:"Compression laps",ar:"وصلات الضغط"},{en:"40Ø; all of them may be at the same section",ar:"40Ø؛ وممكن كلها تبقى في نفس القطاع"}],[{en:"Couplers and welding",ar:"الجلب واللحام"},{en:"bars Ø16 and more; a coupler develops at least 1.25 fy; welding at most 25 % of the bars at one section, the others staggered 20Ø",ar:"أسياخ Ø16 وأكبر؛ الجلبة بتستحمل على الأقل 1.25 fy؛ واللحام لـ 25% من الأسياخ على الأكتر في القطاع والباقي متبادل 20Ø"}],[{en:"Beam cut-offs",ar:"توقيف أسياخ الكمرات"},{en:"1/3 of the bottom bars run through, 2/3 stop 0.1 Ln (end) or 0.125 Ln (interior or cantilever support); top bars Ln/3 and Ln/5; end bars for wL²/24 over 0.15 Ln, anchored Ld; hangers lapped 250 mm; cantilever top steel in two halves, one running 1.5 Lc into the span, both turned down at the tip; inclined beams on their inclined clear length L′n (end bars for wLL′/24)",ar:"تلت الحديد السفلي بيكمّل، والتلتين بيقفوا 0.1 Ln (ركيزة طرفية) أو 0.125 Ln (ركيزة وسطية أو ركيزة كابولي)؛ والعلوي Ln/3 و Ln/5؛ وحديد الأطراف لـ wL²/24 على 0.15 Ln ومتثبت Ld؛ وكانات التعليق بتراكب 250 مم؛ وحديد الكابولي العلوي نصين، نص بيدخل 1.5 Lc في البحر والاتنين بينزلوا عند الطرف؛ والكمرات المائلة على طولها الصافي المائل L′n (وحديد الأطراف لـ wLL′/24)"}]],caption:{en:"Everything below builds on these without repeating them.",ar:"كل اللي جاي مبني على دول من غير ما نعيدهم."}},{t:"p",text:{en:"**Example** with the market rule, Ø22 bars: a bottom bar in tension needs $60\\times22 = 1320$ mm, the same bar at the top $1.3\\times1320 = 1716$ mm, and in compression (a column lap) $40\\times22 = 880$ mm. In a long tension member built from 12 m bars, join them by couplers or welding: with 8 bars, weld at most $0.25\\times8 = 2$ at one section and the next ones $20\\times22 = 440$ mm further on.",ar:"**مثال** بالقاعدة العملية، أسياخ Ø22: السيخ السفلي في الشد محتاج $60\\times22 = 1320$ مم، ونفس السيخ لو علوي $1.3\\times1320 = 1716$ مم، وفي الضغط (وصلة عمود) $40\\times22 = 880$ مم. وفي عنصر شد طويل من أسياخ 12 م، وصّلهم بجلب أو لحام: لو 8 أسياخ، الحم 2 على الأكتر ($0.25\\times8 = 2$) في القطاع الواحد واللي بعدهم على بعد $20\\times22 = 440$ مم."}},{t:"note",tone:"code",text:{en:"The rules of this episode come from two editions of the Egyptian code: the 2020 edition for bond, splices, covers and columns, the 2018 edition for solid, flat and hollow-block slabs. Where the code leaves a choice, the common Egyptian practice is given with it.",ar:"قواعد الحلقة دي جاية من إصدارين من الكود المصري: إصدار 2020 للتماسك والوصلات والغطاء الخرساني والأعمدة، وإصدار 2018 للبلاطات المصمتة واللاكمرية والهوردي. ولما الكود يسيب اختيار، بنذكر معاه الممارسة المصرية المعتادة."}},{t:"quiz",q:{kind:"num",q:{en:"A tension tie of 12 bars is joined by welding. At most how many bars may be welded at the same section?",ar:"شداد من 12 سيخ بيتوصل باللحام. أقصى عدد أسياخ ممكن يتلحم في نفس القطاع؟"},answer:3,tol:.001,explain:{en:"25 % of 12 = 3; the other bars are welded 20Ø further along.",ar:"25% من 12 = 3؛ والباقي بيتلحم على بعد 20Ø."}}}]},{id:"beams",title:{en:"Beam sections: rows, diameters, hangers and side bars",ar:"قطاعات الكمرات: الصفوف والأقطار وكانات التعليق وحديد الجوانب"},blocks:[{t:"p",text:{en:"Main bars of beams are **Ø12 to Ø25**, in **at most three rows** with **at least two bars in every row**. The clear gap between bars is the largest of 25 mm, the biggest bar and the aggregate size + 5 mm — about 25 mm — so a row of width b takes $n = (b - 25)/(\\phi + 25)$ bars, rounded down. In a T- or L-beam only the **web** b counts; in a box section the whole width B. The bars of an upper row sit **exactly above** those of the row below, with a short spacer bar (about Ø20–25) laid across between the rows, so that concrete can flow down between the bars.",ar:"الحديد الرئيسي في الكمرات من **Ø12 لـ Ø25**، في **3 صفوف على الأكتر** و**سيخين على الأقل في كل صف**. المسافة الصافية بين الأسياخ هي الأكبر من 25 مم وقطر أكبر سيخ ومقاس الزلط + 5 مم — حوالي 25 مم — فالصف اللي عرضه b بياخد $n = (b - 25)/(\\phi + 25)$ سيخ، بالتقريب لتحت. في الكمرة T أو L بنحسب عرض **الجسم** b بس؛ وفي القطاع الصندوقي العرض كله B. أسياخ الصف اللي فوق بتبقى **فوق** أسياخ الصف اللي تحت بالظبط، وبينهم سيخ فاصل قصير (حوالي Ø20–25) معدّي بالعرض، علشان الخرسانة تنزل بين الأسياخ."}},{t:"eq",tex:"n = \\dfrac{b - 25}{\\phi + 25}",caption:{en:"Bars per row (b and Ø in mm, round down).",ar:"عدد الأسياخ في الصف (b و Ø بالمم، بالتقريب لتحت)."}},{t:"p",text:{en:"**Two diameters** in one layer only if they are **neighbours** in the series 12-16-18-22-25, with **at least two bars of each** and the **bigger ones in the corners** (they hold the stirrup corners): 2Ø12 + 2Ø18 is wrong (not neighbours), 2Ø12 + 1Ø16 is wrong (one bar only). **Compression steel** is kept at most $0.40\\,A_s$ — beyond that, deepen the beam. **Stirrup hangers** carry the stirrups where no top steel is needed: 10–20 % of $A_s$ and never less than 2Ø10 in an ordinary beam; $0.4\\,A_s$ and never less than 2Ø12 in a frame member. When the web below the slab is deeper than **600 mm** (the older code said t > 700 mm) each side face gets **shrinkage bars**: at least $0.08\\,A_s$ per side, bars Ø10 or more at no more than 300 mm — the height $t - 100$ is split into $\\lceil (t - 100)/300 \\rceil$ spaces. **Stirrups** are at least 5Ø8 per metre, closed, their hooks on the compression side and alternating from one stirrup to the next. And a beam end where the analysis gives no moment still gets top steel for $wL^2/24$.",ar:"**قطرين** في نفس الطبقة بس لو **متجاورين** في السلسلة 12-16-18-22-25، و**سيخين على الأقل من كل قطر**، و**الأكبر في الأركان** (هما اللي ماسكين أركان الكانة): 2Ø12 + 2Ø18 غلط (مش متجاورين)، و 2Ø12 + 1Ø16 غلط (سيخ واحد بس). **حديد الضغط** بيفضل $0.40\\,A_s$ على الأكتر — أكتر من كده عمّق الكمرة. **كانات التعليق** بتشيل الكانات في المكان اللي مش محتاج حديد علوي: 10–20% من $A_s$ ومش أقل من 2Ø10 في الكمرة العادية؛ و $0.4\\,A_s$ ومش أقل من 2Ø12 في عنصر الإطار. ولما جسم الكمرة تحت البلاطة يبقى أعمق من **600 مم** (الكود القديم كان بيقول t > 700 مم) كل وش جانبي بياخد **حديد انكماش**: على الأقل $0.08\\,A_s$ لكل ناحية، أسياخ Ø10 أو أكبر كل 300 مم على الأكتر — والارتفاع $t - 100$ بيتقسم $\\lceil (t - 100)/300 \\rceil$ مسافة. و**الكانات** على الأقل 5Ø8 في المتر، مقفولة، وجنشها في ناحية الضغط ومتبادل من كانة للتانية. وطرف الكمرة اللي التحليل مابيديلوش عزم بياخد برضه حديد علوي لعزم $wL^2/24$."}},{t:"table",head:["Ø (mm)","8","10","12","16","18","22","25"],rows:[[{en:"area of one bar (mm²)",ar:"مساحة السيخ (مم²)"},"50.3","78.5","113","201","254","380","491"]],caption:{en:"Read the tables of several bars with care: nine Ø6 bars are 254.5 mm² — the same as one Ø18.",ar:"اقرا جداول مجموعات الأسياخ بحرص: تسع أسياخ Ø6 مساحتهم 254.5 مم² — زي سيخ Ø18 واحد."}},{t:"p",text:{en:"**Example.** A 300 × 900 T-beam under a 150 mm slab needs 6Ø22 ($A_s = 2281$ mm²). Per row $n = (300 - 25)/(22 + 25) = 5.85 \\to 5$ bars; five and one is not allowed (a row of one bar), so **4 + 2**. The web is $900 - 150 = 750 > 600$ mm deep: $\\lceil 800/300 \\rceil = 3$ spaces, i.e. **2 bars per side**, and each side needs $0.08\\times2281 = 182.5$ mm²: 2Ø10 (157) are too little, **2Ø12** (226) are enough. Hangers: 10–20 % of $A_s$ is 228–456 mm² → **2Ø16** (402). Stirrups at least 5Ø8/m.",ar:"**مثال.** كمرة T مقاسها 300 × 900 تحت بلاطة 150 مم محتاجة 6Ø22 ($A_s = 2281$ مم²). في الصف $n = (300 - 25)/(22 + 25) = 5.85 \\to 5$ أسياخ؛ خمسة وواحد مش مسموح (صف فيه سيخ واحد)، يبقى **4 + 2**. جسم الكمرة عمقه $900 - 150 = 750 > 600$ مم: $\\lceil 800/300 \\rceil = 3$ مسافات، يعني **سيخين في كل ناحية**، وكل ناحية محتاجة $0.08\\times2281 = 182.5$ مم²: 2Ø10 (157) مش كفاية، و**2Ø12** (226) كفاية. كانات التعليق: 10–20% من $A_s$ يعني 228–456 مم² ← **2Ø16** (402). والكانات على الأقل 5Ø8 في المتر."}},{t:"lab",lab:"detailing",height:470,props:{mode:"gallery",lockMode:!0,item:"beam",items:["beam","hinge"],missions:a},caption:{en:'The gallery: bars as coloured tubes, the checker below. Turn on "Section" to cut the beam open.',ar:"المعرض: الأسياخ أنابيب ملونة والمراجعة تحت. شغّل «قطاع» علشان تفتح الكمرة."}},{t:"p",text:{en:"**Bent bars** («أسياخ مكسحة»), the older system: two thirds of the bottom steel is bent up at 45° — at 0.1 L from an end support and at L/5 from an interior one — and carried L/3 past the support as top steel; straight top bars are added where the bent bars are not enough. **Intermediate hinge** («مفصلة وسطية»): a joint that passes N and V but no moment, as in a short suspended span resting on two cantilevers — a **floating bay** («باكية عائمة»). It is built as a halving joint: each part ends in a nib about half the depth, the nibs overlap with a **20 mm gap** and a bearing pad between them, and both nibs get inclined bars and closed stirrups, because the re-entrant corners are where they crack first.",ar:"**الأسياخ المكسحة**، النظام الأقدم: تلتين الحديد السفلي بيتكسّح لفوق بزاوية 45° — عند 0.1 L من الركيزة الطرفية وعند L/5 من الوسطية — ويكمّل L/3 بعد الركيزة كحديد علوي؛ ولو الأسياخ المكسحة مش كفاية بنزوّد أسياخ علوية مستقيمة. **المفصلة الوسطية**: وصلة بتنقل N و V من غير عزم، زي بحر قصير متعلق على كابوليين — **باكية عائمة**. وبتتعمل وصلة نص على نص: كل جزء بينتهي بكتف (Nib) عمقه حوالي نص الكمرة، والكتفين بيركبوا على بعض بـ**فاصل 20 مم** ولوح ارتكاز بينهم، وكل كتف بياخد أسياخ مائلة وكانات مقفولة، لأن الأركان الداخلية هي أول مكان بيتشرخ."}},{t:"p",text:{en:"**Dapped ends of a long floating girder** — a link bridge of about 20 m between two buildings, or a floating bay resting on cantilevers: the girder end is cut down to a nib about half its depth, sitting on a bearing pad on a short cantilever (corbel). Check the **shear of the reduced nib section** with its own depth, not the girder's. Bend the main bottom bars up at 45° into the top of the nib and hook them; add horizontal U-loops in the nib; group **hanger stirrups** at the re-entrant corner, enough to lift the whole reaction back into the full girder ($A = R/(f_y/\\gamma_s)$); hook the top bars down at the end. **Example:** $R = 400$ kN on a 400 mm wide nib with $d = 450$ mm, $f_{cu} = 30$ N/mm²: $q_u = 400\\times10^3/(400\\times450) = 2.22 \\le 0.7\\sqrt{30/1.5} = 3.13$ N/mm² ✓; hangers $400\\times10^3/(400/1.15) = 1150$ mm² → 8 two-leg Ø10 stirrups (1257 mm²) next to the corner.",ar:"**الأطراف المتدرّجة (Dapped ends) لكمرة عائمة طويلة** — كوبري وصلة حوالي 20 م بين مبنيين، أو باكية عائمة قاعدة على كوابيل: طرف الكمرة بيتقص لكتف (Nib) عمقه حوالي نص عمقها، قاعد على لوح ارتكاز فوق كابولي قصير. راجع **القص في قطاع الكتف المقصوص** بعمقه هو، مش بعمق الكمرة. اكسح الحديد السفلي الرئيسي بزاوية 45° لفوق الكتف وجنّشه؛ وضيف أسياخ U أفقية في الكتف؛ وجمّع **كانات تعليق** عند الركن الداخلي، كفاية ترفع رد الفعل كله تاني للكمرة الكاملة ($A = R/(f_y/\\gamma_s)$)؛ وجنّش الحديد العلوي لتحت عند الطرف. **مثال:** $R = 400$ kN على كتف عرضه 400 مم و $d = 450$ مم، و $f_{cu} = 30$ N/mm²: $q_u = 400\\times10^3/(400\\times450) = 2.22 \\le 0.7\\sqrt{30/1.5} = 3.13$ N/mm² ✓؛ وكانات التعليق $400\\times10^3/(400/1.15) = 1150$ مم² ← 8 كانات Ø10 بفرعين (1257 مم²) جنب الركن."}},{t:"quiz",q:{kind:"num",q:{en:"A 350 mm wide web with Ø25 bars. How many bars fit in one row?",ar:"جسم كمرة عرضه 350 مم وأسياخ Ø25. كام سيخ يدخل في الصف الواحد؟"},answer:6,tol:.001,explain:{en:"$n = (350 - 25)/(25 + 25) = 6.5 \\to 6$ bars.",ar:"$n = (350 - 25)/(25 + 25) = 6.5 \\to 6$ أسياخ."}}}]},{id:"joints",title:{en:"Joints and frames: opening, closing, three members",ar:"العقد والإطارات: بتفتح وبتقفل وتلات عناصر"},blocks:[{t:"p",text:{en:'At every corner ask where the tension is. **Tension on the inner faces** — the moments of the two members "overlap" («تداخل») — opens the corner: a tension bar bent round the re-entrant corner pulls its two legs together, their resultant points **out** of the concrete and tears the cover off. That detail is fatal. Let the bars cross instead — **scissors** («مقص»): each bar runs straight across the joint and is anchored $L_d \\approx 60\\phi$ on the far side, with the stirrups of the two members overlapping — preferred in beams; or tie the corner with a **bow** («فيونكة», a loop bar) — preferred in slabs and walls. **Tension on the outer faces** — the moments "spread" («تباعد») — closes the corner: the bars run continuously round it, because now their resultant pushes **into** the concrete; or each bar is extended $L_d$ past the corner.',ar:"عند كل ركن اسأل الشد فين. **الشد على الوشوش الداخلية** — عزوم العنصرين «متداخلة» — بيفتح الركن: سيخ الشد المتني حوالين الركن الداخلي بيشد رجليه على بعض، ومحصلتهم رايحة **بره** الخرسانة وبتقلع الغطاء. التفصيلة دي قاتلة. خلّي الأسياخ تتقاطع بدالها — **المقص**: كل سيخ بيعدّي العقدة على استقامته وبيتثبت $L_d \\approx 60\\phi$ في الناحية التانية، وكانات العنصرين متداخلة — ده المفضل في الكمرات؛ أو اربط الركن بـ**فيونكة** (سيخ على شكل عروة) — دي المفضلة في البلاطات والحوائط. **الشد على الوشوش الخارجية** — العزوم «متباعدة» — بيقفل الركن: الأسياخ بتلف حواليه من غير قطع، لأن محصلتها دلوقتي بتضغط **جوه** الخرسانة؛ أو كل سيخ بيتمد $L_d$ بعد الركن."}},{t:"p",text:{en:"A **three-member joint** balances $M_1 = M_2 + M_3$. Look at the members two by two: detail the **closing** pair first (continuous bars), then add the **scissors** of the opening pair; the third pair has no relation. A four-member joint is detailed pair by pair in the same way. And when a member is meant to be hinged at a joint, the hinge is built a distance **d** away from the joint, not inside it.",ar:"**عقدة التلات عناصر** بتتزن $M_1 = M_2 + M_3$. بص على العناصر اتنين اتنين: سلّح الزوج اللي **بيقفل** الأول (أسياخ مستمرة)، وبعدين ضيف **مقص** الزوج اللي بيفتح؛ والزوج التالت مالوش علاقة. وعقدة الأربع عناصر بتتسلح زوج زوج بنفس الطريقة. ولو عنصر المفروض يبقى مفصلي عند عقدة، المفصلة بتتعمل على بعد **d** من العقدة، مش جواها."}},{t:"lab",lab:"detailing",height:470,props:{mode:"gallery",lockMode:!0,item:"knee",items:["knee","joint3"],missions:n},caption:{en:"Switch the knee between closing and opening, then try the three details; the arrow shows where the bent bar pulls.",ar:"حوّل الركن بين بيقفل وبيفتح وجرّب التلات تفاصيل؛ السهم بيوري السيخ المتني بيشد فين."}},{t:"p",text:{en:"**Frames.** A beam–column joint is **rigid** when the column is at least $0.8$ of the beam depth ($t_c \\ge 0.8\\,t_b$) and acts as a **hinge** when it is about half ($t_c = t_b/2$). Column steel follows the support case: in a column hinged at one end and rigid at the other, half of the outer steel runs the full height and half is curtailed; the inner face gets hangers of about $0.4\\,A_s$ (tension failure) or $A'_s = A_s$ (compression failure), with the ties concentrated over 1.0 m or h/3 next to the hinge. A link member's bars simply become dowels. In a column rigid at both ends the tension-face bars come out of the footing continuously or are lap-spliced — never dowels; where the moment changes sign at a height y, half of that steel stops at $y + L_a$; reversible moments (max-max) give symmetric steel. At a rigid two-member joint with different steel, the smaller area runs round the corner and the excess is anchored $L_d$.",ar:"**الإطارات.** عقدة الكمرة مع العمود بتبقى **جاسئة** لما العمود يبقى على الأقل $0.8$ من عمق الكمرة ($t_c \\ge 0.8\\,t_b$)، وبتشتغل **مفصلة** لما يبقى حوالي النص ($t_c = t_b/2$). حديد العمود بيمشي مع نوع الركيزة: في عمود مفصلي من طرف وجاسئ من التاني، نص الحديد الخارجي بيكمّل الارتفاع كله والنص بيقف؛ والوش الداخلي بياخد حديد تعليق حوالي $0.4\\,A_s$ (انهيار شد) أو $A'_s = A_s$ (انهيار ضغط)، والكانات متركزة على 1.0 م أو h/3 جنب المفصلة. وأسياخ الوصلة (Link) بتبقى أشاير وخلاص. وفي عمود جاسئ من الطرفين أسياخ وش الشد بتطلع من القاعدة مستمرة أو بتتوصل بالتراكب — عمرها ما تبقى أشاير؛ ولو العزم بيقلب إشارته عند ارتفاع y، نص الحديد ده بيقف عند $y + L_a$؛ والعزوم اللي بتعكس (max-max) بتدي حديد متماثل. وفي عقدة جاسئة من عنصرين حديدهم مختلف، المساحة الأصغر بتلف حوالين الركن والزيادة بتتثبت $L_d$."}},{t:"p",text:{en:"**Drawing a frame.** First the concrete outline around the centre lines: a member of constant depth t/2 on each side; one of variable depth with its centre line in the middle of the smaller depth; a hinged base t/4 + t/4 about the axis; a link member t/2 at both ends. Then the steel, always in this order:",ar:"**رسم الإطار.** الأول خط الخرسانة حوالين المحاور: العنصر الثابت العمق t/2 على كل ناحية؛ والمتغير العمق محوره في نص العمق الأصغر؛ والركيزة المفصلية t/4 + t/4 حوالين المحور؛ والوصلة t/2 عند الطرفين. وبعدين الحديد، دايماً بالترتيب ده:"}},{t:"steps",items:[{en:"The main steel along every tension face.",ar:"الحديد الرئيسي على كل وش شد."},{en:"The joints: continuous bars at closing corners, scissors or bows at opening ones.",ar:"العقد: أسياخ مستمرة عند الأركان اللي بتقفل، ومقص أو فيونكة عند اللي بتفتح."},{en:"The inner steel.",ar:"الحديد الداخلي."},{en:"The ends of the members: dowels, anchorages, bars turned into cantilevers.",ar:"أطراف العناصر: أشاير وتثبيت وأسياخ متنية جوه الكوابيل."},{en:"Curtailment in steps of the moment of resistance.",ar:"توقيف الأسياخ على درجات عزم المقاومة."},{en:"Stirrup hangers.",ar:"كانات التعليق."},{en:"Stirrups, shrinkage bars and buckling bars.",ar:"الكانات وحديد الانكماش وحديد الانبعاج."},{en:"The bar schedule («تفريد»).",ar:"جدول تفريد الحديد."}]},{t:"p",text:{en:"**Example.** A column 600 mm deep meets a girder 700 mm deep: $600/700 = 0.857 \\ge 0.8$ → a rigid joint. At its closing knee the girder needs 5Ø25 and the column 3Ø25: three bars run round the corner, the two extra girder bars are anchored $60\\times25 = 1500$ mm into the column. The base of a 500 mm column that is meant to be hinged is drawn $500/4 = 125$ mm each side of its axis.",ar:"**مثال.** عمود عمقه 600 مم بيقابل كمرة عمقها 700 مم: $600/700 = 0.857 \\ge 0.8$ ← عقدة جاسئة. عند ركنه اللي بيقفل الكمرة محتاجة 5Ø25 والعمود 3Ø25: تلات أسياخ بتلف حوالين الركن، والسيخين الزيادة في الكمرة بيتثبتوا $60\\times25 = 1500$ مم جوه العمود. وقاعدة عمود 500 مم المفروض تبقى مفصلية بترتسم $500/4 = 125$ مم على كل ناحية من محوره."}},{t:"p",text:{en:"**Hall frames on the drawing board.** The same rules, met again and again in the large-span systems:",ar:"**إطارات الصالات على لوحة الرسم.** نفس القواعد، وبتتكرر كتير في أنظمة البحور الكبيرة:"}},{t:"steps",items:[{en:"**Hinged feet**: the column tapers to about half its knee depth at the foot; short **crossed dowels** pass through the narrowed throat into the footing — they carry the normal force and the shear, not a moment.",ar:"**الرجول المفصلية**: العمود بيتدرّج لحوالي نص عمق ركنه عند الرجل؛ و**أشاير متقاطعة** قصيرة بتعدّي من الرقبة الضيقة للقاعدة — بتشيل القوة العمودية والقص، مش عزم."},{en:"**Knees**: the outer bars run continuously round the corner and down the outer face of the column. At every **re-entrant soffit corner** — the kink at the end of a haunch, the apex of a gable (the bottom bars cross at the ridge), the corners of a trapezoidal frame — the bars **cross** (scissors), each anchored past the corner.",ar:"**الأركان**: الأسياخ الخارجية بتلف حوالين الركن من غير قطع وبتنزل على الوش الخارجي للعمود. وعند كل **ركن داخلي في البطن** — الكسرة في آخر الفيونكة، وتاج الجمالوني (الأسياخ السفلية بتتقاطع عند التاج)، وأركان الإطار شبه المنحرف — الأسياخ **بتتقاطع** (مقص)، وكل سيخ متثبت بعد الركن."},{en:"**A girder that must pass no moment into a column** needs no corbel: its bars enter the column **straight**, without being bent down it.",ar:"**كمرة لازم ماتنقلش عزم للعمود** مش محتاجة كابولي قصير: أسياخها بتدخل العمود **مستقيمة**، من غير ما تتني لتحت فيه."},{en:"**Real supports**: a real hinge is a bearing pad with a dowel, a real roller a pad only; a roller end on a short corbel gets closely spaced stirrups in the beam end and in the corbel. On real supports there is no $wL^2/24$ end moment, so the top bars there are only stirrup hangers.",ar:"**الركائز الحقيقية**: المفصلة الحقيقية لوح ارتكاز بشاير (Dowel)، والركيزة المتحركة الحقيقية لوح بس؛ والطرف المتحرك على كابولي قصير بياخد كانات متقاربة في طرف الكمرة وفي الكابولي. وعلى الركائز الحقيقية مفيش عزم طرفي $wL^2/24$، فالحديد العلوي هناك كانات تعليق بس."},{en:"**A shared column head** carrying two girders or two arch girders (at an expansion joint, say): a **Y-shaped head** of two short cantilevers, each girder end on its own bearing — a hinge on one, a roller on the other — with a 20 mm gap between the ends; the arch axis, the tie axis and the column axis meet over the bearing.",ar:"**راس عمود مشترك** شايل كمرتين أو كمرتين مقوّستين (عند فاصل تمدد مثلاً): **راس على شكل Y** من كابولين قصيرين، كل طرف كمرة على ارتكازه — مفصلة على واحد ومتحركة على التاني — وبين الطرفين 20 مم؛ ومحور العقد ومحور الشداد ومحور العمود بيتقابلوا فوق الارتكاز."},{en:"**A column or a cantilever frame standing on a lower frame**: its bars run through the lower knee and are anchored $L_d$ into the lower column — $40\\phi$ for compression bars, 800 mm for Ø20.",ar:"**عمود أو إطار كابولي واقف على إطار أوطى**: أسياخه بتعدّي الركن اللي تحت وبتتثبت $L_d$ جوه العمود اللي تحت — $40\\phi$ لأسياخ الضغط، يعني 800 مم لـ Ø20."},{en:"**A tie that stretches** — and a joint that is never a perfect hinge — gives the column top a small moment: continue the rafter or girder bars down into the column. A **thick column** that takes a thrust alone has its main bars on the tension face and only hangers on the other.",ar:"**الشداد اللي بيستطيل** — والوصلة اللي عمرها ما بتبقى مفصلة كاملة — بيدّوا راس العمود عزم صغير: كمّل أسياخ الكمرة المائلة أو الكمرة لتحت جوه العمود. و**العمود التخين** اللي بياخد الدفع لوحده حديده الرئيسي على وش الشد وعلى الوش التاني حديد تعليق بس."},{en:"**A knee whose moment reverses** — a frame pushed sideways at one knee by more than twice its own thrust: the main bars of that column move to its **inner** face and run into the bottom of the beam; the outer face gets nominal bars.",ar:"**ركن عزمه بيعكس** — إطار مزقوق لجنب عند ركن بأكتر من ضعف دفعه هو: الحديد الرئيسي في العمود ده بينتقل لوشه **الداخلي** وبيدخل في بطن الكمرة؛ والوش الخارجي بياخد أسياخ إنشائية."},{en:"**On the drawing**: footings under columns with a moment are drawn shifted; main bars, nominal bars and dowels are told apart by colour or line weight, and every bar is drawn again on its own in the bar diagram.",ar:"**في الرسم**: القواعد اللي تحت أعمدة عليها عزم بترتسم مترحّلة؛ والحديد الرئيسي والإنشائي والأشاير بيتميّزوا باللون أو بتخانة الخط، وكل سيخ بيترسم تاني لوحده في التفريد."}]},{t:"p",text:{en:"**Example.** A two-hinged frame with 1200 mm knees tapers to 600 mm at its feet; 4Ø22 crossed dowels need $40\\times22 = 880$ mm into the footing and into the column. An upper column with Ø20 bars standing on its knee is anchored $40\\times20 = 800$ mm into the lower column.",ar:"**مثال.** إطار ذو مفصلين أركانه 1200 مم بيتدرّج لـ 600 مم عند رجوله؛ والأشاير المتقاطعة 4Ø22 محتاجة $40\\times22 = 880$ مم جوه القاعدة وجوه العمود. وعمود فوق بأسياخ Ø20 واقف على ركنه بيتثبت $40\\times20 = 800$ مم جوه العمود اللي تحت."}},{t:"p",text:{en:"**The bars of a hall frame, type by type.** In the frames of the large-span halls the knee steel, the span steel and the column steel stop at fixed fractions of the span and of the column height:",ar:"**أسياخ إطار الصالة، نوع نوع.** في إطارات صالات البحور الكبيرة حديد الركن وحديد البحر وحديد العمود بيقفوا عند كسور ثابتة من البحر ومن ارتفاع العمود:"}},{t:"table",head:[{en:"Bars",ar:"الأسياخ"},{en:"three-hinged",ar:"ثلاثي المفصلات"},{en:"two-hinged",ar:"ذو مفصلين"},{en:"fixed bases",ar:"ثابت الركائز"},{en:"gable",ar:"جمالوني"}],rows:[[{en:"extra top bars at the knee, into the beam",ar:"الأسياخ العلوية الزيادة عند الركن، جوه الكمرة"},"$L/3$",{en:"two groups, to $L/5$ and $L/4$",ar:"مجموعتين، لحد $L/5$ و $L/4$"},{en:"$L/5$ and $L/4$",ar:"$L/5$ و $L/4$"},{en:"$L'/5$ and $L'/4$ along the rafter",ar:"$L'/5$ و $L'/4$ على الكمرة المائلة"}],[{en:"bottom bars of the span",ar:"الأسياخ السفلية في البحر"},"—",{en:"half run into the knee, half stop $0.15L$ before it",ar:"نصها بيدخل الركن، ونصها بيقف قبله بـ $0.15L$"},{en:"the same",ar:"نفس الحكاية"},{en:"half stop $0.15L'$ before the knee",ar:"نصها بيقف قبل الركن بـ $0.15L'$"}],[{en:"outer face of the column",ar:"الوش الخارجي للعمود"},{en:"the knee steel in two halves round the corner; the extra bars stop $H/3$ above the hinge",ar:"حديد الركن على نصين حوالين الركن؛ والأسياخ الزيادة بتقف فوق المفصلة بـ $H/3$"},{en:"the same",ar:"نفس الحكاية"},{en:"half to two thirds of the knee steel run down to $H/3$ above the footing and lap there on starter bars that rise $H/3$ (at least $40\\phi$ and 1.0 m); the rest stop higher",ar:"من النص للتلتين من حديد الركن بينزلوا لحد $H/3$ فوق القاعدة وبيتراكبوا هناك على أشاير طالعة $H/3$ (على الأقل $40\\phi$ و 1.0 م)؛ والباقي بيقف أعلى"},{en:"as its bases",ar:"حسب ركائزه"}],[{en:"inner face of the column",ar:"الوش الداخلي للعمود"},{en:"hangers of about $0.4\\,A_s$",ar:"حديد تعليق حوالي $0.4\\,A_s$"},{en:"the same",ar:"نفس الحكاية"},{en:"L-bars hooked in the footing, rising $2H/3$; hangers of about $0.4\\,A_s$ above them",ar:"أسياخ L متجنشة في القاعدة وطالعة $2H/3$؛ وفوقها حديد تعليق حوالي $0.4\\,A_s$"},{en:"as its bases",ar:"حسب ركائزه"}],[{en:"stirrups next to a hinge",ar:"الكانات جنب المفصلة"},{en:"10Ø10/m over 1.0 m or $t$ (the larger), at the crown and at the base",ar:"10Ø10/م على 1.0 م أو $t$ (الأكبر)، عند التاج وعند القاعدة"},{en:"the same, at the base",ar:"نفس الحكاية، عند القاعدة"},{en:"— (the lap of the starter bars instead)",ar:"— (بدالها تراكب الأشاير)"},{en:"at the base hinges; crossed stirrups in the ridge block",ar:"عند مفصلات القاعدة؛ وكانات متقاطعة في عقدة التاج"}]],caption:{en:"Lengths from the knee along the beam (L = span; L' = sloping length of the two rafters together) and from the hinge or the footing up the column (H = column height); A_s = steel of the column at the knee.",ar:"الأطوال من الركن على طول الكمرة (L = البحر؛ و L' = الطول المايل للكمرتين المائلتين مع بعض) ومن المفصلة أو القاعدة لفوق في العمود (H = ارتفاع العمود)؛ و A_s = حديد العمود عند الركن."}},{t:"steps",items:[{en:"**In every hall frame**: side bars 2Ø10 every 300 mm on each face of the beam and 2Ø12 every 250 mm on each face of the column; column ties 5Ø8/m; hangers of $0.4\\,A_s$ — a frame member, not an ordinary beam with its $(0.1 \\to 0.2)\\,A_s$ — on the bottom of the beam next to the knee, and on top over the middle of a two-hinged or fixed beam. In the knee the stirrups of beam and column overlap into a mesh, a **U-bar** closes the corner, and a few bars are bent diagonally across it from the inner face of the column into the top of the beam.",ar:"**في كل إطار صالة**: حديد جوانب 2Ø10 كل 300 مم على كل وش للكمرة و 2Ø12 كل 250 مم على كل وش للعمود؛ وكانات العمود 5Ø8/م؛ وحديد تعليق $0.4\\,A_s$ — عنصر إطار، مش كمرة عادية بالـ $(0.1 \\to 0.2)\\,A_s$ بتاعتها — تحت في الكمرة جنب الركن، وفوق في نص كمرة الإطار ذو المفصلين أو الثابت. وجوه الركن كانات الكمرة والعمود بتتداخل وتعمل شبكة، و**سيخ على شكل U** بيقفل الركن، وكام سيخ بيتكسحوا بالقطر عبره من الوش الداخلي للعمود لفوق الكمرة."},{en:"**The crown hinge** of a three-hinged frame: each half-beam tapers from $t$ at the knee to $X = t/2$ at the crown, its top face kept horizontal. Two notches leave a **neck** $X/3$ deep at mid-height, the 2 cm gap lying in the notches. The main top and bottom bars of each half are closed into a **U** at the joint face, and separate **hinge bars** cross through the neck as an X, with straight legs into both halves.",ar:"**مفصلة التاج** في الإطار ثلاثي المفصلات: كل نص كمرة بيتدرّج من $t$ عند الركن لـ $X = t/2$ عند التاج، ووشه العلوي فاضل أفقي. ونقرتين بيسيبوا **رقبة** عمقها $X/3$ في نص الارتفاع، وفتحة الـ 2 سم جوه النقرتين. والأسياخ الرئيسية العلوية والسفلية لكل نص بتتقفل على شكل **U** عند وش الوصلة، و**أسياخ المفصلة** لوحدها بتتقاطع في الرقبة على شكل X، ورجليها مستقيمة جوه النصين."},{en:"**A real base hinge** is built the same way: the column foot, $t/2$ deep, sits on a neoprene or lead plate $X/3$ wide, with dowels through it against horizontal movement. **A fixed base** gets real L-bars, hooked in the footing, on the face that the base moment puts in tension, and only **starter bars** on the other face.",ar:"**المفصلة الحقيقية عند القاعدة** بتتعمل بنفس الطريقة: رجل العمود، وعمقها $t/2$، قاعدة على لوح نيوبرين أو رصاص عرضه $X/3$، وأشاير معدّية فيه ضد الحركة الأفقية. و**الركيزة الثابتة** بتاخد أسياخ L حقيقية، متجنشة في القاعدة، على الوش اللي عزم القاعدة بيشده، و**أشاير** بس على الوش التاني."},{en:"**A tie at the eaves** runs full length and is looped round the joints at its ends, where the column bars are continued in; a **hanger** from the apex is a U-bar hooked over the rafter top bars and round the tie. **At a ridge** the inner bars of each rafter cross and are anchored in the top of the other, and the outer bars bend over the top.",ar:"**الشداد عند منسوب الأركان** بيمشي بطوله كله ومتلفوف حوالين العقد اللي في أطرافه، واللي أسياخ العمود بتكمّل جواها؛ و**المعلّق** من التاج سيخ على شكل U متجنش فوق الأسياخ العلوية للكمرة المائلة وحوالين الشداد. و**عند التاج** الأسياخ الداخلية لكل كمرة مائلة بتتقاطع وبتتثبت في الجزء العلوي من التانية، والأسياخ الخارجية بتتني فوق التاج."},{en:"**The middle column of a continuous frame** is tapered from both faces down to its hinge; its bars run up into the beam and are bent into it on both sides, and the top bars of the beam over it are curtailed in staggered groups on both sides.",ar:"**العمود اللي في النص في الإطار المستمر** بيتدرّج من الوشين لحد مفصلته؛ وأسياخه بتطلع جوه الكمرة وبتتني فيها من الناحيتين، والأسياخ العلوية للكمرة فوقه بتقف على مجموعات متدرّجة على الناحيتين."}]},{t:"p",text:{en:"**Example.** A two-hinged frame, $L = 20$ m, $H = 7.5$ m, $t = 1.5$ m: the knee bars stop $20/5 = 4.0$ m and $20/4 = 5.0$ m from the knee; half the bottom bars stop $0.15\\times20 = 3.0$ m before each knee; the extra column bars stop $7.5/3 = 2.5$ m above the hinge, and 10Ø10/m run over 1.5 m above it ($t > 1.0$ m). On fixed bases the inner L-bars rise $2\\times7.5/3 = 5.0$ m and the outer starter bars 2.5 m — more than the $\\max(40\\times25,\\ 1000) = 1000$ mm lap of Ø25. A three-hinged frame of 15 m with $t = 1.5$ m: each half ends 0.75 m deep at the crown with a neck of $0.75/3 = 0.25$ m, and its extra knee bars run $15/3 = 5.0$ m along the beam.",ar:"**مثال.** إطار ذو مفصلين، $L = 20$ م، و $H = 7.5$ م، و $t = 1.5$ م: أسياخ الركن بتقف على بعد $20/5 = 4.0$ م و $20/4 = 5.0$ م من الركن؛ ونص الأسياخ السفلية بيقف قبل كل ركن بـ $0.15\\times20 = 3.0$ م؛ وأسياخ العمود الزيادة بتقف فوق المفصلة بـ $7.5/3 = 2.5$ م، و 10Ø10/م على 1.5 م فوقها ($t > 1.0$ م). وعلى ركائز ثابتة أسياخ L الداخلية بتطلع $2\\times7.5/3 = 5.0$ م والأشاير الخارجية 2.5 م — أكتر من تراكب Ø25 اللي هو $\\max(40\\times25,\\ 1000) = 1000$ مم. وإطار ثلاثي المفصلات 15 م و $t = 1.5$ م: كل نص بينتهي بعمق 0.75 م عند التاج ورقبة $0.75/3 = 0.25$ م، وأسياخ الركن الزيادة بتمشي $15/3 = 5.0$ م على طول الكمرة."}},{t:"quiz",q:{kind:"mcq",q:{en:"A column 400 mm deep meets a girder 800 mm deep. The joint is treated as…",ar:"عمود عمقه 400 مم بيقابل كمرة عمقها 800 مم. العقدة بتتعامل على إنها…"},options:[{en:"rigid",ar:"جاسئة"},{en:"a hinge",ar:"مفصلة"},{en:"a closing knee whatever the loads",ar:"ركن بيقفل مهما كانت الأحمال"}],answer:1,explain:{en:"$t_c = t_b/2$: the column is too slender to fix the girder — the joint acts as a hinge.",ar:"$t_c = t_b/2$: العمود أرفع من إنه يثبّت الكمرة — العقدة بتشتغل مفصلة."}}}]},{id:"col-bars",title:{en:"Columns: cover, fire and the longitudinal bars",ar:"الأعمدة: الغطاء الخرساني والحريق والحديد الطولي"},blocks:[{t:"p",text:{en:"The **concrete cover** protects the steel from corrosion and from fire. Against corrosion it depends on the exposure — case 1 for dry interiors up to case 4 for the most aggressive surroundings — and on the concrete strength:",ar:"**الغطاء الخرساني** بيحمي الحديد من الصدأ ومن الحريق. ضد الصدأ بيعتمد على التعرض — الحالة 1 للأماكن الداخلية الجافة لحد الحالة 4 لأعنف ظروف — وعلى رتبة الخرسانة:"}},{t:"table",head:[{en:"Clear cover (mm)",ar:"الغطاء الصافي (مم)"},{en:"case 1",ar:"حالة 1"},{en:"case 2",ar:"حالة 2"},{en:"case 3",ar:"حالة 3"},{en:"case 4",ar:"حالة 4"}],rows:[[{en:"all members except walls and solid slabs, fcu ≤ 25",ar:"كل العناصر ما عدا الحوائط والبلاطات المصمتة، fcu ≤ 25"},"25","30","35","45"],[{en:"the same, fcu > 25",ar:"نفسها، fcu > 25"},"20","25","30","40"],[{en:"walls and solid slabs, fcu ≤ 25",ar:"الحوائط والبلاطات المصمتة، fcu ≤ 25"},"20","25","30","40"],[{en:"the same, fcu > 25",ar:"نفسها، fcu > 25"},"20","20","25","35"]]},{t:"table",head:[{en:"Fire rating",ar:"مقاومة الحريق"},"½ h","1 h","1½ h","2 h","3 h","4 h"],rows:[[{en:"smallest column side, carbonate aggregate (mm)",ar:"أصغر ضلع للعمود، ركام جيري (مم)"},"200","200","250","250","300","400"],[{en:"smallest column side, siliceous aggregate (mm)",ar:"أصغر ضلع للعمود، ركام سيليسي (مم)"},"200","200","250","300","400","450"],[{en:"smallest column side, medium-weight concrete (mm)",ar:"أصغر ضلع للعمود، خرسانة متوسطة الوزن (مم)"},"200","200","250","250","300","400"],[{en:"cover to the main bars (mm)",ar:"الغطاء للحديد الرئيسي (مم)"},"20","25","35","40","45","50"]],caption:{en:"A column that must stand longer in a fire needs more concrete around and inside the cage.",ar:"العمود اللي لازم يستحمل حريق مدة أطول محتاج خرسانة أكتر حوالين القفص وجواه."}},{t:"p",text:{en:"The **longitudinal bars**: at least **Ø12**, in practice not more than **Ø25**; on the perimeter only, with a bar in **every corner**; at least **4 bars** in a rectangular column (only up to 300 × 300 may it have just four) and **6** in a circular one; two diameters only if they are neighbours; in an axially loaded column an even number of each diameter placed symmetrically, the bigger ones at the corners. The **clear gap** between neighbouring bars must not exceed **250 mm** (and not be less than 25 mm or the bar size); the bar centres sit about 50 mm inside the faces.",ar:"**الحديد الطولي**: على الأقل **Ø12**، وعملياً مش أكبر من **Ø25**؛ على المحيط بس، وسيخ في **كل ركن**؛ وعلى الأقل **4 أسياخ** في العمود المستطيل (وماينفعش 4 بس غير لحد 300 × 300)، و**6** في الدائري؛ وقطرين بس لو متجاورين؛ وفي العمود المحمل محورياً عدد زوجي من كل قطر متوزع بتماثل والأكبر في الأركان. و**المسافة الصافية** بين الأسياخ المتجاورة ماتزيدش عن **250 مم** (وماتقلش عن 25 مم أو قطر السيخ)؛ ومحاور الأسياخ حوالي 50 مم جوه الوشوش."}},{t:"p",text:{en:"**Example.** A 400 × 400 column that must resist 2 h of fire with siliceous aggregate: its side must be at least 300 mm ✓ and the cover 40 mm — Ø20 bars centred 50 mm from the faces have exactly $50 - 10 = 40$ mm ✓. In exposure case 3 with fcu = 30 the ties need 30 mm: $40 - 8 = 32$ mm with Ø8 ties ✓. A 250 × 600 column asked to resist 3 h with carbonate aggregate fails at once: it needs a 300 mm side.",ar:"**مثال.** عمود 400 × 400 لازم يستحمل حريق ساعتين وركامه سيليسي: ضلعه لازم يبقى 300 مم على الأقل ✓ والغطاء 40 مم — أسياخ Ø20 محاورها على 50 مم من الوشوش ليها $50 - 10 = 40$ مم بالظبط ✓. وفي حالة التعرض 3 و fcu = 30 الكانات محتاجة 30 مم: $40 - 8 = 32$ مم بكانات Ø8 ✓. وعمود 250 × 600 مطلوب يستحمل 3 ساعات بركام جيري بيقع من أول خطوة: محتاج ضلع 300 مم."}},{t:"quiz",q:{kind:"num",q:{en:"The 700 mm face of a 300 × 700 column carries 3Ø16 (bar centres 50 mm from the faces). Clear gap between neighbouring bars (mm)?",ar:"الوش 700 مم لعمود 300 × 700 عليه 3Ø16 (محاور الأسياخ على 50 مم من الوشوش). المسافة الصافية بين الأسياخ المتجاورة (مم)؟"},answer:284,tol:.005,unit:"mm",explain:{en:"$(700 - 100)/2 - 16 = 284 > 250$ mm: a fourth bar is needed on that face.",ar:"$(700 - 100)/2 - 16 = 284 > 250$ مم: الوش ده محتاج سيخ رابع."}}}]},{id:"col-ties",title:{en:"Confinement and ties",ar:"الحصر والكانات"},blocks:[{t:"p",text:{en:"Squeezed concrete swells sideways. **Ties** hold the swelling back: between two tie corners the concrete arches, and between two tie levels it arches again, so only the core inside those arches is truly **confined** («خرسانة محصورة»). Every **inner tie** adds corners and shrinks the unconfined bites; a **spiral** («حلزون») confines uniformly and keeps carrying load long after the peak — the most ductile column. Ties also hold the bars during casting and stop the compressed bars from buckling outwards.",ar:"الخرسانة المضغوطة بتنتفخ على الجناب. **الكانات** بتمسك الانتفاخ ده: بين ركنين كانة الخرسانة بتعمل عقد، وبين مستويين كانات بتعمل عقد تاني، فالقلب اللي جوه العقود دي بس هو اللي **محصور** فعلاً. وكل **كانة داخلية** بتزود أركان وبتصغّر المناطق اللي مش محصورة؛ و**الحلزون** بيحصر بانتظام وبيفضل شايل حمل بعد الذروة بكتير — أكتر عمود مطيلية. والكانات كمان بتمسك الأسياخ وقت الصب وبتمنع الأسياخ المضغوطة من إنها تنبعج لبره."}},{t:"steps",items:[{en:"One **outer tie** encloses all the bars; tie corners bend at most 135°.",ar:"**كانة خارجية** واحدة بتلف على كل الأسياخ؛ وأركان الكانة زاويتها 135° على الأكتر."},{en:"Tie legs at most **300 mm** apart: a bar more than **150 mm** (clear) from a bar held by a tie corner must be held itself, by a cross-tie («كانة رباط») or an inner tie. A face of 400 mm or less carrying four bars or more gets an inner tie when the outer legs are more than 300 mm apart.",ar:"فروع الكانة على الأكتر **300 مم** من بعض: السيخ اللي أبعد من **150 مم** (صافي) عن سيخ ماسكه ركن كانة لازم يتمسك هو كمان، بكانة رباط (حبّاية) أو كانة داخلية. والوش اللي عرضه 400 مم أو أقل وعليه 4 أسياخ أو أكتر بياخد كانة داخلية لما فروع الكانة الخارجية تبعد أكتر من 300 مم."},{en:"Circular columns: circular ties or a spiral, and **no inner ties**.",ar:"الأعمدة الدائرية: كانات دايرية أو حلزون، و**من غير كانات داخلية**."},{en:"Tie diameter $\\phi_t \\ge \\max(8,\\ \\phi_L/4)$; spacing $s \\le \\min(200,\\ 15\\phi_L)$ with the smallest bar.",ar:"قطر الكانة $\\phi_t \\ge \\max(8,\\ \\phi_L/4)$؛ والتباعد $s \\le \\min(200,\\ 15\\phi_L)$ بأصغر سيخ."},{en:"Volume of ties in a metre of column ≥ **0.25 %** of the concrete volume of that metre.",ar:"حجم الكانات في متر العمود ≥ **0.25%** من حجم الخرسانة في المتر ده."},{en:'One bar wound round the middle bars in "eyes" («كانة عيون») is **not** a substitute for inner ties.',ar:"سيخ واحد ملفوف على الأسياخ الوسطانية على شكل عيون (كانة عيون) **مش** بديل عن الكانات الداخلية."}]},{t:"eq",tex:["\\phi_t \\ge \\max\\left(8,\\ \\dfrac{\\phi_L}{4}\\right),\\qquad s \\le \\min(200,\\ 15\\,\\phi_L)","n\\,A_{\\phi t}\\,L_t \\ge 0.0025\\,A_c\\times1000"],caption:{en:"L_t = length of one set of ties (outer tie plus cross-ties) along their centre lines; n = ties per metre.",ar:"L_t = طول طقم الكانات (الخارجية + الرباط) على محاورها؛ و n = عدد الكانات في المتر."}},{t:"p",text:{en:"**Example.** A 350 × 700 column with 10Ø18: three bars on each 350 face, four on each 700 face. On the long faces the bars are $(700 - 100)/3 = 200$ mm apart, $200 - 18 = 182 > 150$ mm clear, so the two middle bars of each long face need **two cross-ties** per set; on the short faces $(350 - 100)/2 - 18 = 107 \\le 150$ mm ✓. Ties $\\ge \\max(8,\\ 18/4) \\to$ Ø8; $s \\le \\min(200,\\ 15\\times18 = 270) = 200$ mm, i.e. 5 per metre. Volume: with the tie axis $50 - 9 - 4 = 37$ mm inside, one set is $2(276 + 626) + 2\\times250 = 2304$ mm long; the rule asks $0.0025\\times350\\times700\\times1000 = 612\\,500$ mm³ per metre, and 5Ø8 give $5\\times50.3\\times2304 \\approx 579\\,500$ ✗ — so **6Ø8 per metre** ($\\approx 695\\,300$ ✓, s ≈ 167 mm): here the volume rule, not the spacing, decides.",ar:"**مثال.** عمود 350 × 700 فيه 10Ø18: تلات أسياخ على كل وش 350، وأربعة على كل وش 700. على الوشوش الطويلة الأسياخ بين بعضها $(700 - 100)/3 = 200$ مم، يعني $200 - 18 = 182 > 150$ مم صافي، فالسيخين الوسطانيين في كل وش طويل محتاجين **كانتين رباط** في كل طقم؛ وعلى الوشوش القصيرة $(350 - 100)/2 - 18 = 107 \\le 150$ مم ✓. الكانات $\\ge \\max(8,\\ 18/4) \\to$ Ø8؛ و $s \\le \\min(200,\\ 15\\times18 = 270) = 200$ مم، يعني 5 في المتر. الحجم: محور الكانة على $50 - 9 - 4 = 37$ مم جوه، فالطقم طوله $2(276 + 626) + 2\\times250 = 2304$ مم؛ والقاعدة بتطلب $0.0025\\times350\\times700\\times1000 = 612\\,500$ مم³ في المتر، و 5Ø8 بيدوا $5\\times50.3\\times2304 \\approx 579\\,500$ ✗ — يبقى **6Ø8 في المتر** ($\\approx 695\\,300$ ✓، و s ≈ 167 مم): هنا قاعدة الحجم هي اللي حكمت مش التباعد."}},{t:"lab",lab:"detailing",height:470,props:{mode:"gallery",lockMode:!0,item:"column",items:["column","dowels","tie"],missions:o},caption:{en:"Change the bars, the ties and the tie layout; every rule is checked live below the stage.",ar:"غيّر الأسياخ والكانات وشكل الكانات؛ وكل قاعدة بتتراجع لايف تحت المشهد."}},{t:"quiz",q:{kind:"num",q:{en:"A 400 × 400 column. Smallest volume of ties per metre of column (×10³ mm³)?",ar:"عمود 400 × 400. أقل حجم كانات في متر العمود (×10³ مم³)؟"},answer:400,tol:.005,explain:{en:"$0.0025\\times400\\times400\\times1000 = 400\\,000$ mm³ = 400 × 10³.",ar:"$0.0025\\times400\\times400\\times1000 = 400\\,000$ مم³ = 400 × 10³."}}}]},{id:"col-floors",title:{en:"From floor to floor: laps, cranks, size changes and hangers",ar:"من دور لدور: الوصلات والتكسيح وتغيير المقاس والشدادات"},blocks:[{t:"p",text:{en:"Column bars are joined **above every slab**: the bars of the lower column stick up as starter bars («أشاير») and lap with the bars above over $\\max(40\\phi,\\ 1.0\\ \\text{m})$. When the upper column is smaller, the lower bars are **cranked** («تكسيح») inside the depth of the beam, with a slope of at most **1 : 6**; if the offset is too big for that, the lower bars stop at the top of the beam and **separate splice bars** run $\\max(40\\phi,\\ 1.0\\ \\text{m})$ into both columns. Through the joint the **column ties continue** — it is the beam stirrups that stop at the column faces. At the bottom, **footing dowels** go at least 40Ø into the footing, down to the bottom mesh and tied to it, and $\\max(40\\phi,\\ 1.0\\ \\text{m})$ up into the column.",ar:"أسياخ الأعمدة بتتوصل **فوق كل بلاطة**: أسياخ العمود اللي تحت بتطلع كـ**أشاير** وبتتراكب مع أسياخ اللي فوق على طول $\\max(40\\phi,\\ 1.0\\ \\text{m})$. ولما العمود اللي فوق يصغر، أسياخ اللي تحت بـ**تتكسّح** جوه عمق الكمرة بميل **1 : 6** على الأكتر؛ ولو الإزاحة أكبر من كده، أسياخ اللي تحت بتقف عند وش الكمرة و**أشاير منفصلة** بتدخل $\\max(40\\phi,\\ 1.0\\ \\text{m})$ في العمودين. وجوه العقدة **كانات العمود بتكمّل** — كانات الكمرة هي اللي بتقف عند وشوش العمود. وتحت، **أشاير القاعدة** بتدخل 40Ø على الأقل جوه القاعدة، لحد الشبكة السفلية ومربوطة فيها، و $\\max(40\\phi,\\ 1.0\\ \\text{m})$ لفوق جوه العمود."}},{t:"p",text:{en:"**Changing the size.** Redesign a column about every two floors and reduce it by **at most 50 mm on each side**. A reduction on **one side only** moves the axis by half of it, so keep it to **40 mm** (the axis moves 20 mm, no more than the minimum eccentricity; 50 mm is accepted in practice) — beyond that the upper column is eccentric and must be designed for M + P. Facade columns, reduced on the inner side only, may drop 100 mm every two floors.",ar:"**تغيير المقاس.** العمود بيتعاد تصميمه كل دورين تقريباً وبيقل **50 مم على الأكتر من كل ناحية**. والتقليل من **ناحية واحدة** بيزق المحور نصه، فخلّيه **40 مم** (المحور بيتحرك 20 مم، مش أكتر من اللامركزية الدنيا؛ وعملياً بيتقبل 50 مم) — أكتر من كده العمود اللي فوق بيبقى لامركزي ولازم يتصمم على M + P. وأعمدة الواجهة، اللي بتقل من جوه بس، ممكن تقل 100 مم كل دورين."}},{t:"p",text:{en:"**Example.** A 600 mm column becomes 500 mm above a 550 mm beam: the bars move $50$ mm on each side, a slope of $50/550 = 1/11 \\le 1/6$ ✓ — crank them. With Ø20 bars the lap above the slab is $\\max(40\\times20 = 800,\\ 1000) = 1000$ mm. A facade column going from 600 to 560 mm on its inner side only: 40 mm, its axis moves 20 mm ✓.",ar:"**مثال.** عمود 600 مم بيبقى 500 مم فوق كمرة عمقها 550 مم: الأسياخ بتتحرك $50$ مم من كل ناحية، يعني ميل $50/550 = 1/11 \\le 1/6$ ✓ — كسّحها. وبأسياخ Ø20 التراكب فوق البلاطة $\\max(40\\times20 = 800,\\ 1000) = 1000$ مم. وعمود واجهة من 600 لـ 560 مم من جوه بس: 40 مم، ومحوره بيتحرك 20 مم ✓."}},{t:"p",text:{en:"**Tension members and hangers.** A tie or a hanger («شداد») cracks, so its steel carries the whole force: $A_s = T_u/(f_y/\\gamma_s)$. Give it a square section of about **20–40** times $A_s$ (never smaller than 250 × 250 mm), symmetric bars, only outer ties 5Ø8/m, and anchor the bars **60Ø** into the members it connects. A hanger that carries a suspended beam takes the beam reaction plus its own weight: $T = R + W_h$. **Example:** $R_u = 520$ kN, a 3.6 m hanger of 250 × 250: own weight $W_h = 1.4\\times25\\times0.25^2\\times3.6 = 7.875$ kN, $T_u = 527.9$ kN, $A_s = 527\\,875/347.83 = 1517.6$ mm² → **8Ø16** (1608.5 mm², symmetric); 20–40 $A_s$ is 32 170–64 340 mm² and 250 × 250 = 62 500 mm² ✓; the bars run $60\\times16 = 960$ mm into the beams.",ar:"**عناصر الشد والشدادات.** الشداد بيتشرخ، فحديده شايل القوة كلها: $A_s = T_u/(f_y/\\gamma_s)$. ادّيله قطاع مربع حوالي **20–40** مرة $A_s$ (ومش أصغر من 250 × 250 مم)، وأسياخ متماثلة، وكانات خارجية بس 5Ø8/م، وثبّت الأسياخ **60Ø** جوه العناصر اللي بيربطها. والشداد اللي شايل كمرة متعلقة بياخد رد فعلها زائد وزنه: $T = R + W_h$. **مثال:** $R_u = 520$ kN وشداد طوله 3.6 م ومقاسه 250 × 250: وزنه $W_h = 1.4\\times25\\times0.25^2\\times3.6 = 7.875$ kN، و $T_u = 527.9$ kN، و $A_s = 527\\,875/347.83 = 1517.6$ مم² ← **8Ø16** (1608.5 مم²، متماثل)؛ و 20–40 $A_s$ يعني 32 170–64 340 مم² و 250 × 250 = 62 500 مم² ✓؛ والأسياخ بتدخل $60\\times16 = 960$ مم جوه الكمرات."}},{t:"quiz",q:{kind:"num",q:{en:"Beam 600 mm deep; the column below is 650 mm, the one above 500 mm (equal on both sides). The crank slope is 1 : ?",ar:"كمرة عمقها 600 مم؛ العمود اللي تحت 650 مم واللي فوق 500 مم (بالتساوي من الناحيتين). ميل التكسيح 1 : ؟"},answer:8,tol:.005,explain:{en:"Offset $(650 - 500)/2 = 75$ mm over 600 mm: $75/600 = 1/8 \\le 1/6$ ✓.",ar:"الإزاحة $(650 - 500)/2 = 75$ مم على 600 مم: $75/600 = 1/8 \\le 1/6$ ✓."}}}]},{id:"slabs",title:{en:"Solid slabs: bars, layers and where they stop",ar:"البلاطات المصمتة: الأسياخ والطبقات وبتقف فين"},blocks:[{t:"p",text:{en:"A slab is designed as a strip 1 m wide — $d = C_1\\sqrt{M/(f_{cu}\\,b)}$ and $A_s = M/(J f_y d)$ with $b = 1000$ mm. Inland Cairo is exposure case 1, coastal Alexandria case 2 (the walls-and-slabs row of the cover table), so with a cover of about 25 mm the main bars have $d = t_s - 30$. Use **5 to 10 bars per metre**, at least Ø8 for mild steel or Ø10 for high-grade steel; $A_{s,min}$ is the larger of $0.6/f_y\\cdot b\\,d$ and 0.15 % of $b\\,d$ (0.25 % for fy 240), and in practice never less than 5Ø10/m (5Ø8/m mild). The bar must not be thicker than about $t_s/10$. Two diameters only if neighbours and equal in number, alternating (3Ø10 + 3Ø12/m, or 2.5Ø10 + 2.5Ø12/m). The **secondary** steel is at least 20 % of the main steel and at least 4Ø8/m (mild) or 4Ø10/m (high grade) — in practice 5Ø10/m. The main bars form the bottom layer, the **«فرش»**; the secondary bars lie on them, the **«غطاء»**. Over a hogging moment only the main bars go to the top: there is no top secondary layer.",ar:"البلاطة بتتصمم كشريحة عرضها 1 م — $d = C_1\\sqrt{M/(f_{cu}\\,b)}$ و $A_s = M/(J f_y d)$ و $b = 1000$ مم. القاهرة من جوه حالة تعرض 1، وإسكندرية على الساحل حالة 2 (سطر الحوائط والبلاطات في جدول الغطاء)، فبغطاء حوالي 25 مم الحديد الرئيسي بياخد $d = t_s - 30$. استخدم **من 5 لـ 10 أسياخ في المتر**، على الأقل Ø8 للحديد الطري أو Ø10 للعالي المقاومة؛ و $A_{s,min}$ هو الأكبر من $0.6/f_y\\cdot b\\,d$ و 0.15% من $b\\,d$ (0.25% لـ fy 240)، وعملياً مش أقل من 5Ø10/م (5Ø8/م طري). والسيخ مايبقاش أتخن من حوالي $t_s/10$. وقطرين بس لو متجاورين وبنفس العدد، بالتبادل (3Ø10 + 3Ø12/م، أو 2.5Ø10 + 2.5Ø12/م). و**الحديد الثانوي** على الأقل 20% من الرئيسي وعلى الأقل 4Ø8/م (طري) أو 4Ø10/م (عالي) — وعملياً 5Ø10/م. الحديد الرئيسي هو الطبقة السفلية، **«الفرش»**؛ والثانوي نايم فوقه، **«الغطاء»**. وفوق العزم السالب الحديد الرئيسي بس هو اللي بيطلع فوق: مفيش طبقة ثانوية علوية."}},{t:"table",head:["t_s (mm)","80","100","120","140","150","≥ 160"],rows:[[{en:"largest bar",ar:"أكبر قطر"},"Ø8","Ø10","Ø12","Ø12","Ø16","Ø16"]],caption:{en:"About t_s/10, rounded to a bar that exists: there is no Ø14 or Ø15, so 140 mm stays at Ø12 while 150 mm already takes Ø16.",ar:"حوالي t_s/10، متقرّب لقطر موجود: مفيش Ø14 ولا Ø15، فالـ 140 مم بتفضل Ø12 والـ 150 مم بتاخد Ø16 على طول."}},{t:"p",text:{en:"**On the plan** a mesh is drawn as two lines; a bar running across the sheet is drawn as it looks in a section (a bottom bar hooks up, a top bar hooks down), and a bar running along the sheet as seen from the right. **Where the bars stop** (straight bars): over a **single span** the alternate bottom bars stop 0.1 L from the supports, and the edge top bars run 0.2 L into the span and are at least a third of the main steel; bent bars bend at 0.1 L. Over **two spans** (X = the larger span) the top bars run X/3 and X/4 past the interior support, alternately; the alternate bottom bars stop 0.15 L from the interior support and 0.1 L from the ends; edge top bars 0.2 L. Over **more than two spans** the top bars run X/4 and X/5, the rest as before (a general sketch that ignores the number of spans simply runs them $L_{max}/3$). Top bars sit on **chairs** («كراسي») and a running support bar, the **string** («وتر»); the $wL^2/24$ edge bars are bent at the outer end only. Designing every bay as a simple span and leaving out the top bars — a site shortcut — cracks the slab over every beam (hidden only where a wall stands there).",ar:"**على اللوحة** الشبكة بتترسم خطين؛ والسيخ اللي ماشي بالعرض في اللوحة بيترسم زي ما بيبان في القطاع (السفلي جنشه لفوق والعلوي جنشه لتحت)، واللي ماشي بالطول زي ما بيتشاف من اليمين. **الأسياخ بتقف فين** (أسياخ مستقيمة): في **بحر واحد** الأسياخ السفلية التبادلية بتقف 0.1 L من الركائز، والحديد العلوي الطرفي بيدخل 0.2 L في البحر ومش أقل من تلت الحديد الرئيسي؛ والأسياخ المكسحة بتتكسح عند 0.1 L. في **بحرين** (X = البحر الأكبر) الحديد العلوي بيدخل X/3 و X/4 بعد الركيزة الوسطية بالتبادل؛ والسفلي التبادلي بيقف 0.15 L من الوسطية و 0.1 L من الأطراف؛ والعلوي الطرفي 0.2 L. وفي **أكتر من بحرين** العلوي X/4 و X/5 والباقي زي ما هو (والرسم العام اللي مابيبصش لعدد البحور بيمده $L_{max}/3$ وخلاص). الحديد العلوي قاعد على **كراسي** وسيخ سند ماشي تحته، **الوتر**؛ وأسياخ $wL^2/24$ الطرفية بتتني من الطرف الخارجي بس. وإنك تصمم كل باكية بسيطة وتشيل الحديد العلوي — اختصار في الموقع — بيشرخ البلاطة فوق كل كمرة (ومستخبي بس لو فيه حائط واقف هناك)."}},{t:"p",text:{en:"**Special cases.** A short bay between two long ones may stay in hogging over its whole length (its smallest moment about $-wL^2/16$): give it a **top mesh** with the main bars on top, a bottom mesh 5Ø10/m both ways for $+wL^2/16$, and run its top bars $L_{max}/4$ into the neighbours. A slab thicker than **160 mm** gets a **top shrinkage mesh** 5Ø10/m both ways (drawn dotted), which also replaces the $wL^2/24$ edge bars. Where the load direction changes from one bay to the next, continue the strip rather than stopping it (that would crack): take the damping moment from the three-moment equation or simply $-wL^2/16$ over the support and $wL^2/8$ in the span, with top bars $L_{max}/3$.",ar:"**حالات خاصة.** باكية قصيرة بين اتنين طوال ممكن تفضل في العزم السالب على طولها كله (أقل عزم فيها حوالي $-wL^2/16$): ادّيها **شبكة علوية** والحديد الرئيسي فوق، وشبكة سفلية 5Ø10/م في الاتجاهين لعزم $+wL^2/16$، ومدّ حديدها العلوي $L_{max}/4$ جوه الباكيات اللي جنبها. والبلاطة اللي أتخن من **160 مم** بتاخد **شبكة انكماش علوية** 5Ø10/م في الاتجاهين (بتترسم منقطة)، وبتغني عن أسياخ $wL^2/24$ الطرفية. ولما اتجاه الحمل يتغير من باكية للتانية، كمّل الشريحة بدل ما توقفها (التوقيف بيشرخ): خد عزم الاستمرار من معادلة الثلاث عزوم أو ببساطة $-wL^2/16$ فوق الركيزة و $wL^2/8$ في البحر، والحديد العلوي $L_{max}/3$."}},{t:"p",text:{en:"**Example.** A 130 mm slab: bars up to Ø12, $d = 100$ mm, $A_{s,min} = 150$ mm²/m → the practical 5Ø10/m (393). With main bars 6Ø12/m (679 mm²) the secondary needs $\\max(0.2\\times679 = 136,\\ 4\\times78.5 = 314) = 314$ mm²/m → 5Ø10/m. Over two spans of 4.2 and 3.6 m: X = 4.2, the top bars run $4.2/3 = 1.40$ m and $4.2/4 = 1.05$ m past the interior support; in the 4.2 m span the alternate bottom bars stop 0.63 m from the interior support and 0.42 m from the end, in the 3.6 m span 0.54 and 0.36 m; the edge top bars run 0.84 and 0.72 m.",ar:"**مثال.** بلاطة 130 مم: الأسياخ لحد Ø12، و $d = 100$ مم، و $A_{s,min} = 150$ مم²/م ← الحد العملي 5Ø10/م (393). ولو الحديد الرئيسي 6Ø12/م (679 مم²) الثانوي محتاج $\\max(0.2\\times679 = 136,\\ 4\\times78.5 = 314) = 314$ مم²/م ← 5Ø10/م. وعلى بحرين 4.2 و 3.6 م: X = 4.2، والعلوي بيدخل $4.2/3 = 1.40$ م و $4.2/4 = 1.05$ م بعد الركيزة الوسطية؛ وفي بحر الـ 4.2 م السفلي التبادلي بيقف 0.63 م من الوسطية و 0.42 م من الطرف، وفي بحر الـ 3.6 م 0.54 و 0.36 م؛ والعلوي الطرفي بيدخل 0.84 و 0.72 م."}},{t:"quiz",q:{kind:"num",q:{en:"A one-way slab over three spans of 3.9, 4.5 and 3.9 m. How far past an interior support do the longer top bars run (m)?",ar:"بلاطة في اتجاه واحد على تلات بحور 3.9 و 4.5 و 3.9 م. الأسياخ العلوية الأطول بتدخل قد إيه بعد الركيزة الوسطية (م)؟"},answer:1.125,tol:.005,unit:"m",explain:{en:"More than two spans: X/4 and X/5 with X = 4.5 m → $4.5/4 = 1.125$ m.",ar:"أكتر من بحرين: X/4 و X/5 و X = 4.5 م ← $4.5/4 = 1.125$ م."}}}]},{id:"cantilevers",title:{en:"Cantilevers, corners, parapets and slab steps",ar:"الكوابيل والأركان والدروات وفروق المناسيب"},blocks:[{t:"p",text:{en:"A **cantilever slab** is at least $L_c/10$ thick, times $(0.4 + f_y/700)$. Its main bars are **top** bars bent into a **fork** («شوكة»): the top leg runs **1.5 Lc** back into the slab behind, turns down at the tip and comes back as a bottom bar along the cantilever. Secondary bars 5Ø10/m go top and bottom. The top bars stand on chairs placed from the back side only — or the bar ends are cranked down to rest on the bottom layer.",ar:"**البلاطة الكابولي** تخانتها على الأقل $L_c/10$ مضروبة في $(0.4 + f_y/700)$. حديدها الرئيسي **علوي** متني على شكل **شوكة**: الرجل العلوية بترجع **1.5 Lc** جوه البلاطة اللي ورا، وبتنزل عند الطرف وترجع كسيخ سفلي على طول الكابولي. والحديد الثانوي 5Ø10/م فوق وتحت. والحديد العلوي واقف على كراسي من الناحية اللي ورا بس — أو أطراف الأسياخ بتتكسح لتحت وتقعد على الطبقة السفلية."}},{t:"eq",tex:"t_s \\ge \\dfrac{L_c}{10}\\left(0.4 + \\dfrac{f_y}{700}\\right)",caption:{en:"With fy = 400 the bracket is 0.971.",ar:"مع fy = 400 القوس بيساوي 0.971."}},{t:"p",text:{en:"Where two cantilevers meet at a **corner**, the corner square has four possible details: **(1)** when $L_c \\le 1.0$ m, just a mesh 5Ø10/m top and bottom; **(2)** when $L_c > 1.0$ m, the top bars of both cantilevers continue across the corner, with 5Ø10/m at the bottom; **(3)** diagonal bars — they work, but the corner gets congested; **(4)** radial (fan) bars — the best behaviour, but hard to cut and bend. A **parapet** («دروة») at the tip adds $w = 1.4\\,b\\,h\\,\\gamma_c$ per metre there; the slab bars are bent up into it and U-bars anchored $L_d$ tie it to the slab (on bridges, closed loops).",ar:"لما كوابيل بيتقابلوا عند **ركن**، مربع الركن ليه أربع تفاصيل: **(1)** لو $L_c \\le 1.0$ م، شبكة 5Ø10/م فوق وتحت وخلاص؛ **(2)** لو $L_c > 1.0$ م، الحديد العلوي للكابوليين بيكمّل ويعدّي في الركن، و 5Ø10/م تحت؛ **(3)** أسياخ قطرية — بتشتغل بس الركن بيتزحم؛ **(4)** أسياخ مروحية — أحسن سلوك، بس تقطيعها وتشكيلها صعب. و**الدروة** عند الطرف بتزوّد $w = 1.4\\,b\\,h\\,\\gamma_c$ لكل متر هناك؛ وحديد البلاطة بيتني لفوق جواها، وأسياخ U متثبتة $L_d$ بتربطها بالبلاطة (في الكباري عُرى مقفولة)."}},{t:"p",text:{en:"**Other slab details.** A cantilever **thicker** than the slab behind it: design the support section with the **smaller** thickness; the thin slab's bottom bars pass the beam axis, the cantilever's stop at mid-beam. A cantilever that **twists** its beam: best make the slab top bars the beam's closed stirrups; with an upturned beam, use a loop so that the cover does not spall. **Double cantilevers** on both sides of a beam: the same bars run continuously over the beam, with closed stirrups to carry the difference of the two moments. Slabs at **different levels** — a bathroom slab dropped 10–15 cm, or a cantilever at a higher level — are either detailed as separate simple slabs (a crack at the beam, and torsion on it) or kept continuous with loops or scissors at the step.",ar:"**تفاصيل تانية للبلاطات.** كابولي **أتخن** من البلاطة اللي وراه: صمّم قطاع الركيزة بالتخانة **الأصغر**؛ وحديد البلاطة الرفيعة السفلي بيعدّي محور الكمرة، وحديد الكابولي بيقف عند نص الكمرة. كابولي **بيلوي** كمرته: الأحسن حديد البلاطة العلوي يبقى هو نفسه كانات الكمرة المقفولة؛ ولو الكمرة مقلوبة استخدم عروة علشان الغطاء مايتقشرش. و**الكابوليين** على جانبي كمرة: نفس الأسياخ بتعدّي مستمرة فوق الكمرة، وكانات مقفولة تشيل فرق العزمين. والبلاطات على **مناسيب مختلفة** — حمام ساقط 10–15 سم، أو كابولي على منسوب أعلى — يا إما بتتسلح كبلاطات بسيطة منفصلة (شرخ عند الكمرة ولي عليها)، يا إما بتفضل مستمرة بعروة أو مقص عند فرق المنسوب."}},{t:"p",text:{en:"**Example.** A 1.8 m balcony, fy = 400: $t_s \\ge 180\\times0.971 = 174.9$ → 180 mm; the fork bars run $1.5\\times1.8 = 2.70$ m back. A 150 × 1100 mm RC parapet at its tip: $w = 1.4\\times0.15\\times1.1\\times25 = 5.775$ kN/m and $M = 5.775\\times1.8 = 10.4$ kN.m per metre at the support. If the balcony turns a corner, $1.8 > 1.0$ m rules out solution 1.",ar:"**مثال.** بلكونة 1.8 م و fy = 400: $t_s \\ge 180\\times0.971 = 174.9$ ← 180 مم؛ والشوكة بترجع $1.5\\times1.8 = 2.70$ م. ودروة خرسانية 150 × 1100 مم عند طرفها: $w = 1.4\\times0.15\\times1.1\\times25 = 5.775$ kN/m و $M = 5.775\\times1.8 = 10.4$ kN.m لكل متر عند الركيزة. ولو البلكونة لفّت ركن، $1.8 > 1.0$ م بتشيل الحل 1 من الحسبة."}},{t:"lab",lab:"detailing",height:470,props:{mode:"gallery",lockMode:!0,item:"corner",items:["cantilever","corner","slabstrip","twoway"],missions:s},caption:{en:"Four slab items: the fork bars, the corner solutions, a continuous strip and a two-way mesh.",ar:"أربع عناصر بلاطات: الشوكة وحلول الركن والشريحة المستمرة وشبكة الاتجاهين."}},{t:"quiz",q:{kind:"num",q:{en:"A 2.1 m cantilever slab, fy = 400. Smallest thickness (mm)?",ar:"بلاطة كابولي 2.1 م و fy = 400. أقل تخانة (مم)؟"},answer:204,tol:.005,unit:"mm",explain:{en:"$2100/10\\times(0.4 + 400/700) = 210\\times0.971 = 204$ mm.",ar:"$2100/10\\times(0.4 + 400/700) = 210\\times0.971 = 204$ مم."}}}]},{id:"twoway",title:{en:"Two-way, inclined, folded and spring slabs",ar:"البلاطات في اتجاهين والمائلة والمنكسرة والمحمولة على بلاطات"},blocks:[{t:"p",text:{en:"In a **two-way slab** the bars of the short direction (the α strip, larger moment) form the bottom layer with a 30 mm cover to their centre: $d = t_s - 30$; the long-direction bars (β) lie on them: $d = t_s - 40$; the top bars also have 30 mm. A slab supported on **two or three sides** only has uncertain loads: analyse it by computer, or carry it in the short direction only — a crack will form along the other — and add a top mesh 5Ø10/m in the other direction. With equal sides, $\\alpha = \\beta = 0.5$.",ar:"في **البلاطة في اتجاهين** أسياخ الاتجاه القصير (شريحة α، العزم الأكبر) هي الطبقة السفلية وغطاؤها لمحورها 30 مم: $d = t_s - 30$؛ وأسياخ الاتجاه الطويل (β) نايمة فوقها: $d = t_s - 40$؛ والحديد العلوي كمان 30 مم. والبلاطة اللي قاعدة على **ضلعين أو تلاتة** بس أحمالها مش مضمونة: حلّها بالكمبيوتر، أو شيلها في الاتجاه القصير بس — وهيطلع شرخ في الاتجاه التاني — وضيف شبكة علوية 5Ø10/م في الاتجاه التاني. ولو الضلعين متساويين $\\alpha = \\beta = 0.5$."}},{t:"p",text:{en:"An **inclined slab** takes its thickness from its true (inclined) lengths and the live load on its horizontal projection; the moments of the horizontal strips are multiplied by $\\cos\\theta$. A **folded slab** is unfolded first and judged one-way or two-way on its true lengths. A **spring slab** (one strip resting on another): solve the carried strip first — it bears on the carrying one over a width X, its reaction R spread as $w = R/X$ — then the carrying strip; the carrying bars form the bottom layer, the carried bars lie on them, and no secondary steel is needed where they overlap.",ar:"**البلاطة المائلة** بتاخد تخانتها من أطوالها الحقيقية (المائلة) والحمل الحي على مسقطها الأفقي؛ وعزوم الشرايح الأفقية بتتضرب في $\\cos\\theta$. و**البلاطة المنكسرة** بتتفرد الأول وبتتحكم عليها اتجاه واحد أو اتجاهين بأطوالها الحقيقية. و**البلاطة المحمولة على بلاطة** (شريحة قاعدة على شريحة): حل الشريحة المحمولة الأول — قاعدة على الشايلة على عرض X، ورد فعلها R بيتوزع $w = R/X$ — وبعدين الشايلة؛ وأسياخ الشايلة هي الطبقة السفلية، والمحمولة فوقها، ومفيش حديد ثانوي في منطقة التقاطع."}},{t:"p",text:{en:"**Example.** A 150 mm two-way slab: $d = 120$ mm for the short bars, 110 mm for the long ones. An inclined strip whose horizontal-strip moment is 18 kN.m/m at 32°: $18\\cos32^\\circ = 15.26$ kN.m/m. A folded slab rising 2.4 m over a 4.0 m run and then running flat for 1.5 m unfolds to $\\sqrt{4.0^2 + 2.4^2} + 1.5 = 6.165$ m: 5.0 m wide it is two-way ($6.165/5.0 = 1.23$), 2.8 m wide one-way ($2.20 > 2$). A carried strip with $R = 12$ kN bearing over $X = 2.4$ m loads the carrying strip with $w = 12/2.4 = 5$ kN/m.",ar:"**مثال.** بلاطة في اتجاهين 150 مم: $d = 120$ مم للأسياخ القصيرة و 110 مم للطويلة. وشريحة مائلة عزم شريحتها الأفقية 18 kN.m/m وزاويتها 32°: $18\\cos32^\\circ = 15.26$ kN.m/m. وبلاطة منكسرة بتطلع 2.4 م على مسقط 4.0 م وبعدين ماشية أفقي 1.5 م بتتفرد لـ $\\sqrt{4.0^2 + 2.4^2} + 1.5 = 6.165$ م: لو عرضها 5.0 م تبقى في اتجاهين ($6.165/5.0 = 1.23$)، ولو 2.8 م في اتجاه واحد ($2.20 > 2$). وشريحة محمولة رد فعلها $R = 12$ kN على عرض $X = 2.4$ م بتحمّل الشايلة $w = 12/2.4 = 5$ kN/m."}},{t:"quiz",q:{kind:"num",q:{en:"A folded slab: 2.1 m rise over a 3.6 m run, then 1.2 m flat; its width is 2.4 m. Unfolded length divided by the width?",ar:"بلاطة منكسرة: 2.1 م طلوع على مسقط 3.6 م، وبعدين 1.2 م أفقي؛ وعرضها 2.4 م. الطول المفرود على العرض؟"},answer:2.24,tol:.005,explain:{en:"$(\\sqrt{3.6^2 + 2.1^2} + 1.2)/2.4 = (4.168 + 1.2)/2.4 = 2.24 > 2$: one-way.",ar:"$(\\sqrt{3.6^2 + 2.1^2} + 1.2)/2.4 = (4.168 + 1.2)/2.4 = 2.24 > 2$: اتجاه واحد."}}}]},{id:"flat",title:{en:"Flat slabs: strips, drop panels and openings",ar:"البلاطات اللاكمرية: الشرائح والسقوط والفتحات"},blocks:[{t:"p",text:{en:"A flat slab carries its full load in both directions, so the **long-direction bars form the bottom layer**. A **drop panel** («سقوط») thickens the slab over a square around the column, a **column head** («تاج العمود») widens the column for heavy loads and punching, and an edge **marginal beam** («كمرة طرفية») must be at least $3t_s$ deep to be stiff enough not to share the slab load. On the plans the widths of the column and field strips are marked, bottom bars drawn solid and top bars dotted.",ar:"البلاطة اللاكمرية بتشيل حملها كله في الاتجاهين، فـ**أسياخ الاتجاه الطويل هي الطبقة السفلية**. و**السقوط** بيتخّن البلاطة على مربع حوالين العمود، و**تاج العمود** بيعرّض العمود للأحمال الكبيرة والقص الثاقب، و**الكمرة الطرفية** على الحرف لازم عمقها على الأقل $3t_s$ علشان تبقى جاسئة كفاية ومتقسمش حمل البلاطة. وعلى اللوحات بتتكتب عروض شرايح الأعمدة والشرايح الوسطى، والحديد السفلي بيترسم متصل والعلوي منقط."}},{t:"table",head:[{en:"Bars",ar:"الأسياخ"},{en:"without drop panels",ar:"من غير سقوط"},{en:"with drop panels",ar:"بسقوط"}],rows:[[{en:"column strip, top, from the column face",ar:"شريحة العمود، علوي، من وش العمود"},"0.30 Ln","0.33 Ln"],[{en:"field strip, top, from the column face",ar:"الشريحة الوسطى، علوي، من وش العمود"},"0.22 Ln","0.22 Ln"],[{en:"bottom U-bars of the drop panel",ar:"أسياخ U السفلية في السقوط"},"—",{en:"≥ 0.5 As of the column strip, max(24Ø, 300 mm) beyond the panel",ar:"≥ 0.5 As لشريحة العمود، max(24Ø, 300 مم) بعد السقوط"}]],caption:{en:"Ln = the larger of the adjacent clear spans. The other bottom bars may stop max(24Ø, 300 mm) from the panel face.",ar:"Ln = الأكبر من البحرين الصافيين المجاورين. وباقي الحديد السفلي ممكن يقف max(24Ø, 300 مم) من وش السقوط."}},{t:"p",text:{en:"Bottom bars of the column zone pass the column face by at least $L_d$, and **at least two bars pass through the column** in each direction; the other bottom bars reach at least 75 mm past an interior column axis and 150 mm past an edge column axis. Top bars at an edge column run $L_d$ past its face, and no top bar stops closer than $L_d + 0.3d$ to a column face. A slab thicker than 160 mm gets a top shrinkage mesh 5Ø10/m. The **edge column strip** gets the steel per metre of an interior column strip when there is no marginal beam, half of it with one. A **cantilever flat slab** has $M = w_s L_c^2/2$ per metre (× L2 per panel): the column strip is designed for the larger of that and $0.25\\,M_o$, the field strip for the larger of that and $0.05\\,M_o$, with fork bars $L_c + 1.5L_c$; parallel to the edge, without a marginal beam the cantilever zone is treated as a column strip (0.25 / 0.50 / 0.45 $M_o$ over the supports, 0.30 / 0.25 $M_o$ in the spans), and with one it is a cantilever solid slab with 5Ø10/m top and bottom.",ar:"الحديد السفلي في منطقة العمود بيعدّي وش العمود على الأقل $L_d$، و**سيخين على الأقل بيعدّوا من جوه العمود** في كل اتجاه؛ وباقي الحديد السفلي بيوصل على الأقل 75 مم بعد محور العمود الداخلي و 150 مم بعد محور العمود الطرفي. والحديد العلوي عند العمود الطرفي بيعدّي وشه $L_d$، ومفيش سيخ علوي بيقف أقرب من $L_d + 0.3d$ لوش عمود. والبلاطة اللي أتخن من 160 مم بتاخد شبكة انكماش علوية 5Ø10/م. و**شريحة العمود الطرفية** بتاخد حديد المتر بتاع شريحة العمود الداخلية لو مفيش كمرة طرفية، ونصه لو فيه. و**البلاطة اللاكمرية الكابولي** عزمها $M = w_s L_c^2/2$ لكل متر (× L2 للباكية): شريحة العمود بتتصمم على الأكبر منه ومن $0.25\\,M_o$، والوسطى على الأكبر منه ومن $0.05\\,M_o$، والشوكة $L_c + 1.5L_c$؛ وموازي للحرف، من غير كمرة طرفية منطقة الكابولي بتتعامل كشريحة عمود (0.25 / 0.50 / 0.45 $M_o$ فوق الركائز، و 0.30 / 0.25 $M_o$ في البحور)، وبكمرة طرفية بتبقى بلاطة مصمتة كابولي بـ 5Ø10/م فوق وتحت."}},{t:"p",text:{en:"**Openings** («فتحات») are allowed with the empirical and frame methods only within limits: in the zone where two field strips cross up to $0.40L_1\\times0.40L_2$; where a column strip crosses a field strip up to a quarter of each strip width; where two column strips cross only $0.05L_1\\times0.05L_2$. Around an opening, **trimming bars** $A'_s = \\tfrac12 A_s\\,b_v$ (with $A_s$ in mm²/m and the opening width $b_v$ in m) go on each side, top and bottom, extended $L_d = 60\\phi$. **Column-head bars**: $A_{s1} \\ge 0.04\\,A_{s1}^{-}\\,L_2$ and $A_{s2} \\ge 0.04\\,A_{s2}^{-}\\,L_1$ (the column-strip hogging steel per metre in each direction times the span across), with ring stirrups and 1Ø10 at the corners. **Punching** is resisted by the concrete alone, or by concrete plus stirrups only when $t_s \\ge 250$ mm. When the slab is analysed by computer, read the contour maps of $M_{11}$ and $M_{22}$, lay basic top and bottom meshes whose capacity is $M = 0.80\\,f_y\\,d\\,A_s$, and add bars only where the contours exceed it.",ar:"**الفتحات** مسموحة مع الطريقة التقريبية وطريقة الإطارات بس في حدود: في منطقة تقاطع شريحتين وسطيتين لحد $0.40L_1\\times0.40L_2$؛ وفي تقاطع شريحة عمود مع وسطى لحد ربع عرض كل شريحة؛ وفي تقاطع شريحتين أعمدة $0.05L_1\\times0.05L_2$ بس. وحوالين الفتحة **حديد تقوية** $A'_s = \\tfrac12 A_s\\,b_v$ (و $A_s$ بالمم²/م وعرض الفتحة $b_v$ بالمتر) من كل ناحية فوق وتحت، ممدود $L_d = 60\\phi$. و**حديد تاج العمود**: $A_{s1} \\ge 0.04\\,A_{s1}^{-}\\,L_2$ و $A_{s2} \\ge 0.04\\,A_{s2}^{-}\\,L_1$ (حديد العزم السالب لشريحة العمود في المتر في كل اتجاه مضروب في البحر العمودي عليه)، مع كانات حلقية و 1Ø10 في الأركان. و**القص الثاقب** بتقاومه الخرسانة لوحدها، أو الخرسانة مع كانات بس لما $t_s \\ge 250$ مم. ولما البلاطة تتحل بالكمبيوتر، اقرا خرايط كنتور $M_{11}$ و $M_{22}$، وحط شبكات أساسية فوق وتحت مقاومتها $M = 0.80\\,f_y\\,d\\,A_s$، وزوّد أسياخ بس في الأماكن اللي الكنتور بيعدّيها."}},{t:"p",text:{en:"**Example.** Drop panels, $L_n = 6.8$ m: the column-strip top bars run $0.33\\times6.8 = 2.24$ m from the column face and the field-strip ones $0.22\\times6.8 = 1.50$ m; the Ø16 U-bars of the drop run $\\max(24\\times16,\\ 300) = 384$ mm beyond it. An 0.8 m opening where two field strips cross in a 7.2 m panel: limit $0.40\\times7.2 = 2.88$ m ✓; with $A_s = 800$ mm²/m the trimming bars are $\\tfrac12\\times800\\times0.8 = 320$ mm² on each side, top and bottom → 2Ø16 (402). Column-head bars for 1200 mm²/m of hogging steel across a 7.2 m panel: $0.04\\times1200\\times7.2 = 345.6$ mm² → 4Ø12 (452). A basic mesh 6Ø12/m at $d = 220$ mm (fy = 400) carries $0.80\\times400\\times220\\times679 = 47.8$ kN.m/m; in a 250 mm slab punching stirrups are allowed.",ar:"**مثال.** بسقوط، و $L_n = 6.8$ م: حديد شريحة العمود العلوي بيدخل $0.33\\times6.8 = 2.24$ م من وش العمود، والوسطى $0.22\\times6.8 = 1.50$ م؛ وأسياخ U الـ Ø16 في السقوط بتعدّيه $\\max(24\\times16,\\ 300) = 384$ مم. وفتحة 0.8 م في تقاطع شريحتين وسطيتين في باكية 7.2 م: الحد $0.40\\times7.2 = 2.88$ م ✓؛ وبـ $A_s = 800$ مم²/م حديد التقوية $\\tfrac12\\times800\\times0.8 = 320$ مم² من كل ناحية فوق وتحت ← 2Ø16 (402). وحديد تاج العمود لحديد سالب 1200 مم²/م على باكية 7.2 م: $0.04\\times1200\\times7.2 = 345.6$ مم² ← 4Ø12 (452). وشبكة أساسية 6Ø12/م على $d = 220$ مم (fy = 400) بتشيل $0.80\\times400\\times220\\times679 = 47.8$ kN.m/m؛ وفي بلاطة 250 مم كانات القص الثاقب مسموحة."}},{t:"quiz",q:{kind:"num",q:{en:"A flat slab without drop panels, Ln = 7.5 m. How far from the column face do the column-strip top bars run (m)?",ar:"بلاطة لاكمرية من غير سقوط، و Ln = 7.5 م. حديد شريحة العمود العلوي بيدخل قد إيه من وش العمود (م)؟"},answer:2.25,tol:.005,unit:"m",explain:{en:"$0.30\\times7.5 = 2.25$ m (with a drop panel it would be $0.33\\times7.5 = 2.475$ m).",ar:"$0.30\\times7.5 = 2.25$ م (بسقوط كانت هتبقى $0.33\\times7.5 = 2.475$ م)."}}}]},{id:"hollow",title:{en:"Hollow-block slabs",ar:"بلاطات الهوردي"},blocks:[{t:"p",text:{en:"The **topping** (50–70 mm) spans between the ribs as a small one-way slab that needs no calculated steel: the code minimum is 3Ø6/m, in practice **5Ø10/m across the ribs (the «فرش») + 4Ø10/m along them (the «غطاء»)** — 4Ø10/m both ways in two-way slabs. Each **rib** («عصب») has 2 (or 4) bars, usually two, and **open stirrups** («كانة شب», open at the top) 5Ø8/m — 4Ø8 or 5Ø8/m in two-way slabs. Blocks are 200 × 400 mm in plan and h = 150, 200 or 250 mm high, weighing about 100, 150 and 200 N — roughly **mass (kg) = h (cm) − 5**; when the block type is unknown, take the heavier cement block. The cover to the bar centres is about 40 mm.",ar:"**البلاطة العلوية** (50–70 مم) بتشيل بين الأعصاب كبلاطة صغيرة في اتجاه واحد مش محتاجة حديد محسوب: الحد الأدنى في الكود 3Ø6/م، وعملياً **5Ø10/م عمودي على الأعصاب (الفرش) + 4Ø10/م موازي ليها (الغطاء)** — و 4Ø10/م في الاتجاهين في الهوردي ذو الاتجاهين. وكل **عصب** فيه سيخين (أو 4)، غالباً اتنين، و**كانات شب** (مفتوحة من فوق) 5Ø8/م — 4Ø8 أو 5Ø8/م في الاتجاهين. والبلوك مسقطه 200 × 400 مم وارتفاعه h = 150 أو 200 أو 250 مم، ووزنه حوالي 100 و 150 و 200 N — تقريباً **الكتلة (كجم) = h (سم) − 5**؛ ولو نوع البلوك مش معروف، خد البلوك الأسمنتي الأتقل. والغطاء لمحاور الأسياخ حوالي 40 مم."}},{t:"table",head:[{en:"Code limit",ar:"حد الكود"},{en:"Value",ar:"القيمة"}],rows:[[{en:"clear distance between ribs e",ar:"المسافة الصافية بين الأعصاب e"},"≤ 700 mm"],[{en:"rib width b",ar:"عرض العصب b"},"≥ max(100 mm, t/3)"],[{en:"topping t_s",ar:"البلاطة العلوية t_s"},"≥ max(50 mm, e/10)"],[{en:"solid strip at the supports X",ar:"الجزء المصمت عند الركائز X"},{en:"≥ 250 mm (practice)",ar:"≥ 250 مم (عملياً)"}],[{en:"rib spacing S, total depth t",ar:"تباعد الأعصاب S والتخانة الكلية t"},"S = e + b, t = h + t_s"]]},{t:"p",text:{en:"**Choosing the system.** The load goes along the ribs. One-way ribs suit $4.5 < L_s \\le 7.0$ m (up to 8.0 m when L.L. ≤ 1.0 kN/m²; ribs may run the long way if that span is not more than 7.0 m); beyond 7.0 m use two-way ribs if $L/L_s \\le 1.5$ (code) — in practice $\\le 4/3$ — otherwise split the panel with a beam. **Cross ribs** («أعصاب عرضية») have the size of the ribs, bottom steel equal to a rib's, top steel at least half of it and closed stirrups 5Ø8/m; their number: none for L.L. ≤ 3 kN/m² and $L_s \\le 5.0$ m, one for L.L. ≤ 3 and $L_s > 5.0$ m, one for L.L. > 3 and $L_s$ = 4.0–7.0 m, three for L.L. > 3 and $L_s > 7.0$ m (an odd number, so that one sits at mid-span). On the plans draw three ribs and the load arrow, the last block of a row reversed; the ribs get 2Ø10 top bars over 0.2 L at the end supports and L/3 at the interior ones; next to a solid slab pick an even number of bars per metre so that they fall into the ribs; the beam gets link bars 1Ø10 every 300 mm. A hollow-block cantilever has fork bars $L_c + 1.5L_c$ and a 250 mm solid edge. A **hidden beam** («كمرة مدفونة») keeps half its bottom steel full length and stops the other half; its top has hangers of 10–20 % $A_s$ and end bars over 0.3 L; its stirrups have many legs, at most 300 mm apart across the width (the inner legs 50–250 mm apart). In practice it is thickened about 70 mm into the 100 mm floor finish, which makes it much narrower.",ar:"**اختيار النظام.** الحمل ماشي مع الأعصاب. الأعصاب في اتجاه واحد مناسبة لـ $4.5 < L_s \\le 7.0$ م (لحد 8.0 م لو الحمل الحي ≤ 1.0 kN/m²؛ وممكن الأعصاب تمشي في الاتجاه الطويل لو البحر ده مش أكتر من 7.0 م)؛ وبعد 7.0 م استخدم أعصاب في الاتجاهين لو $L/L_s \\le 1.5$ (الكود) — وعملياً $\\le 4/3$ — غير كده قسّم الباكية بكمرة. و**الأعصاب العرضية** بنفس مقاس الأعصاب، وحديدها السفلي زي حديد العصب، والعلوي على الأقل نصه، وكانات مقفولة 5Ø8/م؛ وعددها: مفيش لو الحمل الحي ≤ 3 kN/m² و $L_s \\le 5.0$ م، وواحد لو الحي ≤ 3 و $L_s > 5.0$ م، وواحد لو الحي > 3 و $L_s$ من 4.0 لـ 7.0 م، وتلاتة لو الحي > 3 و $L_s > 7.0$ م (عدد فردي علشان واحد يقع في النص). وعلى اللوحات ارسم تلات أعصاب وسهم الحمل، وآخر بلوكة في الصف مقلوبة؛ والأعصاب بتاخد 2Ø10 علوي على 0.2 L عند الركائز الطرفية و L/3 عند الوسطية؛ وجنب بلاطة مصمتة اختار عدد أسياخ زوجي في المتر علشان يقعوا في الأعصاب؛ والكمرة بتاخد أسياخ ربط 1Ø10 كل 300 مم. والهوردي الكابولي شوكته $L_c + 1.5L_c$ وحرفه مصمت 250 مم. و**الكمرة المدفونة** بتكمّل نص حديدها السفلي على طولها وتوقف النص التاني؛ وفوق كانات تعليق 10–20% $A_s$ وحديد أطراف على 0.3 L؛ وكاناتها فروع كتير، على الأكتر 300 مم بين الفرع والتاني بالعرض (والفروع الداخلية 50–250 مم من بعض). وعملياً بتتخن حوالي 70 مم جوه تشطيب الأرضية اللي 100 مم، فبتضيق كتير."}},{t:"p",text:{en:"**Example.** Blocks 250 mm high (about 20 kg), ribs 120 mm, e = 500 mm, topping 60 mm: $t = 310$ mm, $b \\ge \\max(100,\\ 103.3)$ ✓, $t_s \\ge \\max(50,\\ 50)$ ✓, S = 620 mm. A 6.2 × 8.6 m panel with L.L. = 4 kN/m² is one-way on 6.2 m with one cross rib; a 7.6 × 9.6 m panel is two-way ($9.6/7.6 = 1.26 \\le 4/3$); a 7.6 × 11.0 m panel ($1.45$) is within the code 1.5 but beyond the practical 4/3 — add a beam.",ar:"**مثال.** بلوك ارتفاعه 250 مم (حوالي 20 كجم)، وأعصاب 120 مم، و e = 500 مم، وبلاطة علوية 60 مم: $t = 310$ مم، و $b \\ge \\max(100,\\ 103.3)$ ✓، و $t_s \\ge \\max(50,\\ 50)$ ✓، و S = 620 مم. وباكية 6.2 × 8.6 م حملها الحي 4 kN/m² بتبقى في اتجاه واحد على 6.2 م بعصب عرضي واحد؛ وباكية 7.6 × 9.6 م في اتجاهين ($9.6/7.6 = 1.26 \\le 4/3$)؛ وباكية 7.6 × 11.0 م ($1.45$) جوه حد الكود 1.5 بس بعد الحد العملي 4/3 — ضيف كمرة."}},{t:"p",text:{en:"**Hollow blocks running on into a solid cantilever** — a ribbed roof with a solid overhang, say: the ribbed and the solid parts overlap, so the steel is given **per rib** — the top bars of every rib run on into the cantilever as its main bars, beside the ribs' bottom bars hooked at the far support — and **1Ø10 between the ribs** is added in the solid part. With ribs every 500 mm and 2Ø12 per rib, the cantilever gets $2\\times(2\\times113 + 78.5) = 609$ mm² per metre.",ar:"**هوردي بيكمّل في كابولي مصمت** — سقف بأعصاب وكابولي مصمت مثلاً: الجزء اللي بأعصاب والمصمت بيتداخلوا، فالحديد بيتدّي **لكل عصب** — الأسياخ العلوية لكل عصب بتكمّل جوه الكابولي وتبقى حديده الرئيسي، جنب الأسياخ السفلية للأعصاب المتجنشة عند الركيزة البعيدة — وبيتزوّد **1Ø10 بين الأعصاب** في الجزء المصمت. ولو الأعصاب كل 500 مم و 2Ø12 لكل عصب، الكابولي بياخد $2\\times(2\\times113 + 78.5) = 609$ مم² في المتر."}},{t:"quiz",q:{kind:"num",q:{en:"Hollow blocks with a clear rib spacing e = 600 mm. Smallest topping thickness (mm)?",ar:"هوردي المسافة الصافية بين أعصابه e = 600 مم. أقل تخانة للبلاطة العلوية (مم)؟"},answer:60,tol:.005,unit:"mm",explain:{en:"$\\max(50,\\ 600/10) = 60$ mm.",ar:"$\\max(50,\\ 600/10) = 60$ مم."}}}]},{id:"footings",title:{en:"Footings, strap beams and combined footings",ar:"القواعد وكمرات الرباط والقواعد المشتركة"},blocks:[{t:"p",text:{en:"An **isolated footing** has a bottom mesh only: bars at least Ø12, 5 to 10 per metre, at least $\\max(1.5d,\\ 5\\phi12)$ mm² per metre, with a 70 mm cover; a top mesh 5Ø12/m is added only when the footing is 1000 mm thick or more. The mesh bars are bent up at their ends and a **tie bar** («سيخ تربيط», 1Ø12) runs along the tops of the bent ends. The column **dowels** go down to the mesh, are bent on it and tied to it — at least 40Ø into the footing — and rise $\\max(40\\phi,\\ 1.0\\ \\text{m})$ into the column; a couple of column ties are placed inside the footing to hold them.",ar:"**القاعدة المنفصلة** ليها شبكة سفلية بس: أسياخ على الأقل Ø12، من 5 لـ 10 في المتر، وعلى الأقل $\\max(1.5d,\\ 5\\phi12)$ مم² في المتر، وغطاء 70 مم؛ والشبكة العلوية 5Ø12/م بتتضاف بس لما تخانة القاعدة تبقى 1000 مم أو أكتر. وأسياخ الشبكة بتتني لفوق عند أطرافها و**سيخ تربيط** (1Ø12) ماشي على رؤوس الأطراف المتنية. و**أشاير** العمود بتنزل لحد الشبكة وبتتني عليها وتتربط فيها — على الأقل 40Ø جوه القاعدة — وبتطلع $\\max(40\\phi,\\ 1.0\\ \\text{m})$ جوه العمود؛ وكام كانة عمود بتتحط جوه القاعدة تمسكها."}},{t:"p",text:{en:"A **strap beam** («كمرة رباط») between the footing at the property line and the inner one has its top bars continuous over the full length, hooked at both ends; its bottom bars lie over each footing zone; the main bars of the two footings run **across** the beam (the footings cantilever from its faces). A **combined footing** has long top bars hooked at one end only, alternating from side to side, and long bottom bars hooked at both ends; under each column a **hidden beam** («كمرة مدفونة») gathers the transverse bottom bars within its width — $b_1 + d$ for a column at the property line, $b_2 + 2d$ for an interior one — and a top transverse mesh 5Ø12/m completes it.",ar:"**كمرة الرباط** (كمرة التحزيم) بين قاعدة حد الجار والقاعدة الداخلية حديدها العلوي مستمر على طولها كله ومجنّش من الطرفين؛ والسفلي نايم فوق منطقة كل قاعدة؛ والحديد الرئيسي للقاعدتين ماشي **عمودي** على الكمرة (القواعد كوابيل من وشوشها). و**القاعدة المشتركة** حديدها العلوي الطولي مجنّش من طرف واحد بس، بالتبادل من ناحية للتانية، والسفلي الطولي مجنّش من الطرفين؛ وتحت كل عمود **كمرة مدفونة** بتلم الحديد السفلي العرضي في عرضها — $b_1 + d$ لعمود حد الجار، و $b_2 + 2d$ للعمود الداخلي — وشبكة علوية عرضية 5Ø12/م بتكمّل الصورة."}},{t:"p",text:{en:"**Example.** A 650 mm footing: $d = 580$ mm, $A_{s,min} = \\max(1.5\\times580,\\ 565) = 870$ mm²/m → 8Ø12/m (905). Ø18 column bars need $40\\times18 = 720$ mm in the footing, but only $650 - 70 - 2\\times12 = 556$ mm are there: they bend on the mesh for the other 164 mm, and rise $\\max(720,\\ 1000) = 1000$ mm into the column. In a combined footing with $d = 750$ mm and 500 mm columns the hidden beams are $0.5 + 0.75 = 1.25$ m wide at the property line and $0.5 + 1.5 = 2.0$ m under the interior column.",ar:"**مثال.** قاعدة 650 مم: $d = 580$ مم، و $A_{s,min} = \\max(1.5\\times580,\\ 565) = 870$ مم²/م ← 8Ø12/م (905). وأسياخ عمود Ø18 محتاجة $40\\times18 = 720$ مم جوه القاعدة، بس الموجود $650 - 70 - 2\\times12 = 556$ مم بس: بتتني على الشبكة للـ 164 مم الباقيين، وبتطلع $\\max(720,\\ 1000) = 1000$ مم جوه العمود. وفي قاعدة مشتركة $d = 750$ مم وأعمدة 500 مم الكمرات المدفونة عرضها $0.5 + 0.75 = 1.25$ م عند حد الجار و $0.5 + 1.5 = 2.0$ م تحت العمود الداخلي."}},{t:"lab",lab:"detailing",height:470,props:{mode:"gallery",lockMode:!0,item:"footing",items:["footing","strap","flat","hollow"],missions:r},caption:{en:"Footings, the strap and the combined footing — and the flat-slab and hollow-block items of the last two sections.",ar:"القواعد وكمرة الرباط والقاعدة المشتركة — وعناصر البلاطة اللاكمرية والهوردي من الجزئين اللي فاتوا."}},{t:"quiz",q:{kind:"num",q:{en:"An 800 mm thick footing. Smallest bottom steel per metre (mm²)?",ar:"قاعدة تخانتها 800 مم. أقل حديد سفلي في المتر (مم²)؟"},answer:1095,tol:.005,unit:"mm²",explain:{en:"$d = 800 - 70 = 730$ mm: $\\max(1.5\\times730,\\ 565) = 1095$ mm²/m.",ar:"$d = 800 - 70 = 730$ مم: $\\max(1.5\\times730,\\ 565) = 1095$ مم²/م."}}}]},{id:"apply",title:{en:"Your building: a column cage, the balcony and a roof knee",ar:"مبناك: قفص عمود والبلكونة وركن السطح"},blocks:[{t:"p",text:{en:"**Column C0-B2** (ground floor, 300 × 500) came out of the slenderness check with **8Ø16** — two bars on each 300 face, four on each 500 face — and ties Ø8 at 6 per metre. Check the cage rule by rule: on the 500 faces the bars are $400/3 = 133.3$ mm apart, $117.3$ mm clear ≤ 150 → the outer tie holds the corners and no cross-tie is needed; the clear gaps (117 and 184 mm) are below 250 ✓; $\\phi_t = 8 \\ge \\max(8,\\ 4)$ ✓; $s = 1000/6 = 167 \\le \\min(200,\\ 240)$ ✓; one set is $2(224 + 424) = 1296$ mm long, so $6\\times50.3\\times1296 \\approx 391\\,000 \\ge 375\\,000$ mm³ ✓. Inside the building (exposure case 1, fcu = 25) the ties need 25 mm and have $50 - 8 - 8 = 34$ ✓; one hour of fire asks a 200 mm side and 25 mm to the bars (42 ✓). Through the 600 mm beams the ties continue: 4 ties inside each joint.",ar:"**العمود C0-B2** (الدور الأرضي، 300 × 500) طلع من مراجعة النحافة بـ **8Ø16** — سيخين على كل وش 300، وأربعة على كل وش 500 — وكانات Ø8 بمعدل 6 في المتر. راجع القفص قاعدة قاعدة: على الوشوش 500 الأسياخ بين بعضها $400/3 = 133.3$ مم، يعني $117.3$ مم صافي ≤ 150 ← الكانة الخارجية ماسكة الأركان ومش محتاجين كانة رباط؛ والمسافات الصافية (117 و 184 مم) أقل من 250 ✓؛ و $\\phi_t = 8 \\ge \\max(8,\\ 4)$ ✓؛ و $s = 1000/6 = 167 \\le \\min(200,\\ 240)$ ✓؛ والطقم طوله $2(224 + 424) = 1296$ مم، يعني $6\\times50.3\\times1296 \\approx 391\\,000 \\ge 375\\,000$ مم³ ✓. وجوه المبنى (حالة تعرض 1، و fcu = 25) الكانات محتاجة 25 مم وليها $50 - 8 - 8 = 34$ ✓؛ وساعة حريق بتطلب ضلع 200 مم و 25 مم للأسياخ (42 ✓). وجوه الكمرات اللي عمقها 600 مم الكانات بتكمّل: 4 كانات جوه كل عقدة."}},{t:"p",text:{en:"B2 stands where the strap beam B1–B2 crosses its inner footing: 700 mm of concrete under the column. The dowels need $40\\times16 = 640$ mm, while $700 - 70 - 2\\times12 = 606$ mm are there: they go down to the bottom bars and bend on them (a foot of about 150 mm, tied), and rise $\\max(640,\\ 1000) = 1000$ mm into the column. Above the first-floor slab the column continues with **6Ø16** (same 300 × 500 section, so nothing to crank): the eight bars of the ground floor stick up **1000 mm** as starter bars and the upper cage laps on them.",ar:"B2 واقف في المكان اللي كمرة الرباط B1–B2 بتعدّي فيه قاعدته الداخلية: 700 مم خرسانة تحت العمود. الأشاير محتاجة $40\\times16 = 640$ مم، والموجود $700 - 70 - 2\\times12 = 606$ مم: فبتنزل لحد الحديد السفلي وبتتني عليه (رجل حوالي 150 مم، مربوطة)، وبتطلع $\\max(640,\\ 1000) = 1000$ مم جوه العمود. وفوق بلاطة الدور الأول العمود بيكمّل بـ **6Ø16** (نفس القطاع 300 × 500، فمفيش تكسيح): التمن أسياخ بتوع الأرضي بيطلعوا **1000 مم** أشاير والقفص اللي فوق بيتراكب عليهم."}},{t:"p",text:{en:"**The balcony** (1.5 m on axis A, 150 mm): $t_s \\ge 150\\times0.971 = 145.7$ mm ✓ and bars up to Ø16 ✓. Its **5Ø12/m fork bars** run $1.5\\times1.5 = 2.25$ m back from the beam axis, turn down at the tip and come back along the bottom to the beam axis: $2.25 + 1.47 + 0.09 + 1.47 = 5.28$ m per bar, 51 bars along the 10 m. Secondary 5Ø10/m (393 mm², more than the 314 needed) top and bottom. If it ever turned the corner of the building, $L_c = 1.5 > 1.0$ m would rule out the plain mesh (solution 1): continue both sets of top bars across the corner, or fan them. A 120 × 1000 mm RC parapet would add $1.4\\times0.12\\times1.0\\times25 = 4.2$ kN/m at the tip, 6.3 kN.m per metre at the support.",ar:"**البلكونة** (1.5 م على المحور A، و 150 مم): $t_s \\ge 150\\times0.971 = 145.7$ مم ✓ والأسياخ لحد Ø16 ✓. **شوكتها 5Ø12/م** بترجع $1.5\\times1.5 = 2.25$ م من محور الكمرة، وبتنزل عند الطرف وترجع على الوش السفلي لحد محور الكمرة: $2.25 + 1.47 + 0.09 + 1.47 = 5.28$ م للسيخ، و 51 سيخ على طول الـ 10 م. والثانوي 5Ø10/م (393 مم²، أكتر من الـ 314 المطلوبين) فوق وتحت. ولو لفّت في يوم ركن المبنى، $L_c = 1.5 > 1.0$ م هتشيل الشبكة العادية (الحل 1): كمّل حديد الاتجاهين العلوي عبر الركن، أو خليه مروحي. ودروة خرسانية 120 × 1000 مم هتزوّد $1.4\\times0.12\\times1.0\\times25 = 4.2$ kN/m عند الطرف، يعني 6.3 kN.m لكل متر عند الركيزة."}},{t:"p",text:{en:"**The roof knee of axis 2 at A2**: the column is 500 mm deep in the plane of the frame, the girder 600: $500/600 = 0.83 \\ge 0.8$ → a **rigid** joint. Under gravity it **closes** (tension on the top of the girder and on the outer face of the column). The girder end moment 44.2 kN.m needs 316 mm² → 2Ø16: bend them round the outer corner and down the outer face of the column, lapping its two outer corner bars over $60\\times16 = 960$ mm; two two-leg Ø8 stirrups ($A_{st} = 93$ mm² per leg) tie the corner.",ar:"**ركن السطح في المحور 2 عند A2**: العمود عمقه 500 مم في مستوى الإطار والكمرة 600: $500/600 = 0.83 \\ge 0.8$ ← عقدة **جاسئة**. وتحت الأحمال الرأسية الركن **بيقفل** (الشد فوق الكمرة وعلى الوش الخارجي للعمود). عزم طرف الكمرة 44.2 kN.m محتاج 316 مم² ← 2Ø16: لفّهم حوالين الركن الخارجي ونزّلهم على الوش الخارجي للعمود، متراكبين مع سيخين الأركان الخارجية على طول $60\\times16 = 960$ مم؛ وكانتين Ø8 بفرعين ($A_{st} = 93$ مم² لكل فرع) بيربطوا الركن."}},{t:"widget",w:"building",props:{focus:"C0-B2",tags:["footings","cols-g","beams-1","slab-1","cols-1","beams-2","slab-2","balcony","rebar-cols","slender-cols","rebar-slabs","frame-analysis","frame-knees","footing-design","element-details"]}},{t:"quiz",q:{kind:"num",q:{en:"Your balcony: total length of one fork bar, from 1.5 Lc behind the beam axis, round the tip and back to the axis (m)?",ar:"بلكونتك: الطول الكلي لسيخ الشوكة الواحد، من 1.5 Lc ورا محور الكمرة لحد الطرف ورجوعه للمحور (م)؟"},answer:5.28,tol:.005,unit:"m",explain:{en:"$2.25 + (1.5 - 0.03) + (0.15 - 0.06) + (1.5 - 0.03) = 5.28$ m.",ar:"$2.25 + (1.5 - 0.03) + (0.15 - 0.06) + (1.5 - 0.03) = 5.28$ م."}}}]}],quiz:[{kind:"num",q:{en:"A 400 mm web with Ø20 bars. Bars per row?",ar:"جسم كمرة 400 مم وأسياخ Ø20. عدد الأسياخ في الصف؟"},answer:8,tol:.001,explain:{en:"$(400 - 25)/(20 + 25) = 8.33 \\to 8$.",ar:"$(400 - 25)/(20 + 25) = 8.33 \\to 8$."}},{kind:"num",q:{en:"A beam 1100 mm deep under a 100 mm slab. Shrinkage bars on each side face?",ar:"كمرة عمقها 1100 مم تحت بلاطة 100 مم. عدد أسياخ الانكماش على كل وش جانبي؟"},answer:3,tol:.001,explain:{en:"Web 1000 > 600 mm; $\\lceil (1100 - 100)/300 \\rceil = 4$ spaces → 3 bars per side.",ar:"الجسم 1000 > 600 مم؛ و $\\lceil (1100 - 100)/300 \\rceil = 4$ مسافات ← 3 أسياخ لكل ناحية."}},{kind:"mcq",q:{en:"2Ø16 in the corners and 2Ø22 between them in one layer is…",ar:"2Ø16 في الأركان و 2Ø22 بينهم في نفس الطبقة…"},options:[{en:"wrong: the diameters are not neighbours, and the bigger bars belong in the corners",ar:"غلط: القطرين مش متجاورين، والأكبر مكانه الأركان"},{en:"fine: two of each",ar:"تمام: اتنين من كل واحد"},{en:"fine if the stirrups are closed",ar:"تمام لو الكانات مقفولة"}],answer:0,explain:{en:"Only neighbours in 12-16-18-22-25 may be mixed (16 and 22 are two steps apart), with the bigger ones in the corners.",ar:"بس المتجاورين في 12-16-18-22-25 ينفع يتخلطوا (16 و 22 بينهم مقاسين)، والأكبر في الأركان."}},{kind:"num",q:{en:"Column bars Ø28 are lapped above a slab. Lap length (mm)?",ar:"أسياخ عمود Ø28 بتتراكب فوق بلاطة. طول التراكب (مم)؟"},answer:1120,tol:.001,unit:"mm",explain:{en:"$\\max(40\\times28,\\ 1000) = 1120$ mm.",ar:"$\\max(40\\times28,\\ 1000) = 1120$ مم."}},{kind:"tf",q:{en:"Ø16 main bars may be used in a 120 mm solid slab.",ar:"ينفع نستخدم حديد رئيسي Ø16 في بلاطة مصمتة 120 مم."},answer:!1,explain:{en:"The largest bar is about $t_s/10$: Ø12 for 120 mm.",ar:"أكبر قطر حوالي $t_s/10$: يعني Ø12 لـ 120 مم."}},{kind:"num",q:{en:"A 160 mm two-way slab. Effective depth of the long-direction (upper-layer) bars (mm)?",ar:"بلاطة في اتجاهين 160 مم. العمق الفعال لأسياخ الاتجاه الطويل (الطبقة اللي فوق) (مم)؟"},answer:120,tol:.001,unit:"mm",explain:{en:"$d = t_s - 40 = 120$ mm; the short bars below have $t_s - 30 = 130$ mm.",ar:"$d = t_s - 40 = 120$ مم؛ والقصيرة اللي تحت ليها $t_s - 30 = 130$ مم."}},{kind:"mcq",q:{en:"In a flat slab with drop panels, the column-strip top bars run from the column face…",ar:"في بلاطة لاكمرية بسقوط، حديد شريحة العمود العلوي بيدخل من وش العمود…"},options:[{en:"0.33 Ln",ar:"0.33 Ln"},{en:"0.30 Ln",ar:"0.30 Ln"},{en:"0.22 Ln",ar:"0.22 Ln"}],answer:0,explain:{en:"0.33 Ln with drop panels, 0.30 Ln without; the field strip 0.22 Ln in both cases.",ar:"0.33 Ln بالسقوط و 0.30 Ln من غيره؛ والشريحة الوسطى 0.22 Ln في الحالتين."}},{kind:"num",q:{en:"An RC parapet 200 mm wide and 1.2 m high at a cantilever tip. Its ultimate load (kN/m)?",ar:"دروة خرسانية عرضها 200 مم وارتفاعها 1.2 م عند طرف كابولي. حملها الأقصى (kN/m)؟"},answer:8.4,tol:.005,unit:"kN/m",explain:{en:"$1.4\\times0.2\\times1.2\\times25 = 8.4$ kN/m.",ar:"$1.4\\times0.2\\times1.2\\times25 = 8.4$ kN/m."}}]};export{i as default};
